INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a2c', '6a422a4790ab47510c6f7a23', 'Evaluate the limit using direct substitution: $\\lim_{x \\to 3} (2x^2 - 5x + 4)$.', '$7$‎‏‎', '$5$', '$17$', '$9$', 'option_a', NULL, 'Since the polynomial function is continuous everywhere, directly substitute $x = 3$:\n$\\lim_{x \\to 3} (2x^2 - 5x + 4) = 2(3)^2 - 5(3) + 4 = 7$.', 1);
