INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a33', '6a422a4790ab47510c6f7a23', 'Evaluate the limit using direct substitution: $\\lim_{x \\to 1} (5x^2 - 3x + 1)$.', '$1$', '$5$', '$3$‎‏‎', '$13$', 'option_c', NULL, 'Since the polynomial function is continuous everywhere, directly substitute $x = 1$:\n$\\lim_{x \\to 1} (5x^2 - 3x + 1) = 5(1)^2 - 3(1) + 1 = 3$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a3f', '6a422a4790ab47510c6f7a3a', 'Evaluate the limit of the rational function: $\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2}$.', '$6$', '$4$‎‏‎', '$2$', '$0$', 'option_b', NULL, 'Factor the numerator as a difference of squares:\n$\\frac{x^2 - 4}{x - 2} = \\frac{(x - 2)(x + 2)}{x - 2} = x + 2$ for $x \\neq 2$.\nTaking the limit: $\\lim_{x \\to 2} (x + 2) = 2 + 2 = 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a41', '6a422a4790ab47510c6f7a3a', 'Evaluate the limit of the rational function: $\\lim_{x \\to 1} \\frac{x^2 - 1}{x - 1}$.', '$2$‎‏‎', '$0$', '$4$', '$0$', 'option_a', NULL, 'Factor the numerator as a difference of squares:\n$\\frac{x^2 - 1}{x - 1} = \\frac{(x - 1)(x + 1)}{x - 1} = x + 1$ for $x \\neq 1$.\nTaking the limit: $\\lim_{x \\to 1} (x + 1) = 1 + 1 = 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a43', '6a422a4790ab47510c6f7a3a', 'Evaluate the limit of the rational function: $\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}$.', '$6$‎‏‎', '$8$', '$4$', '$0$', 'option_a', NULL, 'Factor the numerator as a difference of squares:\n$\\frac{x^2 - 9}{x - 3} = \\frac{(x - 3)(x + 3)}{x - 3} = x + 3$ for $x \\neq 3$.\nTaking the limit: $\\lim_{x \\to 3} (x + 3) = 3 + 3 = 6$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a4a', '6a422a4790ab47510c6f7a3a', 'Evaluate the limit of the rational function: $\\lim_{x \\to 1} \\frac{x^2 - 1}{x - 1}$.', '$2$‎‏‎', '$4$', '$0$', '$0$', 'option_a', NULL, 'Factor the numerator as a difference of squares:\n$\\frac{x^2 - 1}{x - 1} = \\frac{(x - 1)(x + 1)}{x - 1} = x + 1$ for $x \\neq 1$.\nTaking the limit: $\\lim_{x \\to 1} (x + 1) = 1 + 1 = 2$.', 1);
