INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a53', '6a422a4790ab47510c6f7a51', 'Evaluate the limit at infinity: $\\lim_{x \\to \\infty} \\frac{6x^2 + 4x}{2x^2 + 2}$.', '$0$', '$\\infty$', '$4$', '$3$‎‏‎', 'option_d', NULL, 'Divide the numerator and denominator by the highest power of $x$, which is $x^2$:\n$\\lim_{x \\to \\infty} \\frac{6 + \\frac{4}{x}}{2 + \\frac{2}{x^2}} = \\frac{6 + 0}{2 + 0} = 3$.', 1);
