INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a61', '6a422a4790ab47510c6f7a51', 'Evaluate the limit at infinity: $\\lim_{x \\to \\infty} \\frac{10x^2 + 3x}{2x^2 + 1}$.', '$0$', '$5$‎‏‎', '$6$', '$\\infty$', 'option_b', NULL, 'Divide the numerator and denominator by the highest power of $x$, which is $x^2$:\n$\\lim_{x \\to \\infty} \\frac{10 + \\frac{3}{x}}{2 + \\frac{1}{x^2}} = \\frac{10 + 0}{2 + 0} = 5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a64', '6a422a4790ab47510c6f7a51', 'Evaluate the limit at infinity: $\\lim_{x \\to \\infty} \\frac{8x^2 + 3x}{2x^2 + 4}$.', '$\\infty$', '$4$‎‏‎', '$5$', '$0$', 'option_b', NULL, 'Divide the numerator and denominator by the highest power of $x$, which is $x^2$:\n$\\lim_{x \\to \\infty} \\frac{8 + \\frac{3}{x}}{2 + \\frac{4}{x^2}} = \\frac{8 + 0}{2 + 0} = 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a66', '6a422a4790ab47510c6f7a51', 'Evaluate the limit at infinity: $\\lim_{x \\to \\infty} \\frac{4x^2 + 5x}{2x^2 + 1}$.', '$0$', '$\\infty$', '$2$‎‏‎', '$3$', 'option_c', NULL, 'Divide the numerator and denominator by the highest power of $x$, which is $x^2$:\n$\\lim_{x \\to \\infty} \\frac{4 + \\frac{5}{x}}{2 + \\frac{1}{x^2}} = \\frac{4 + 0}{2 + 0} = 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a6b', '6a422a4790ab47510c6f7a68', 'Evaluate the trigonometric limit: $\\lim_{x \\to 0} \\frac{\\sin(4x)}{x}$.', '$6$', '$1$', '$0$', '$4$‎‏‎', 'option_d', NULL, 'Using the standard limit theorem $\\lim_{\\theta \\to 0} \\frac{\\sin \\theta}{\\theta} = 1$, we can rewrite the expression:\n$\\lim_{x \\to 0} \\frac{\\sin(4x)}{x} = 4 \\times \\lim_{x \\to 0} \\frac{\\sin(4x)}{4x} = 4 \\times 1 = 4$.', 1);
