INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a88', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 2x^2 + 5x$ at the point where $x = 3$.', '$17$‎‏‎', '$14$', '$20$', '$11$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(2)x + 5 = 4x + 5$.\nEvaluate this derivative at $x = 3$ to find the gradient:\n$m = 4(3) + 5 = 12 + 5 = 17$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a8a', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 4x^2 + 4x$ at the point where $x = 2$.', '$20$‎‏‎', '$23$', '$17$', '$12$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(4)x + 4 = 8x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 8(2) + 4 = 16 + 4 = 20$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a8b', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 5x^2 + 5x$ at the point where $x = 3$.', '$38$', '$20$', '$35$‎‏‎', '$32$', 'option_c', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(5)x + 5 = 10x + 5$.\nEvaluate this derivative at $x = 3$ to find the gradient:\n$m = 10(3) + 5 = 30 + 5 = 35$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a8d', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 3x^2 + 4x$ at the point where $x = 2$.', '$16$‎‏‎', '$13$', '$19$', '$10$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(3)x + 4 = 6x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 6(2) + 4 = 12 + 4 = 16$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a86', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 4x^2 + 3x$ at the point where $x = 1$.', '$8$', '$7$', '$14$', '$11$‎‏‎', 'option_d', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(4)x + 3 = 8x + 3$.\nEvaluate this derivative at $x = 1$ to find the gradient:\n$m = 8(1) + 3 = 8 + 3 = 11$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a87', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 5x^2 + 4x$ at the point where $x = 2$.', '$24$‎‏‎', '$27$', '$21$', '$14$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(5)x + 4 = 10x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 10(2) + 4 = 20 + 4 = 24$.', 1);
