INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a90', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 2x^2 + 4x$ at the point where $x = 2$.', '$8$', '$15$', '$9$', '$12$‎‏‎', 'option_d', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(2)x + 4 = 4x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 4(2) + 4 = 8 + 4 = 12$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a92', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 4x^2 + 3x$ at the point where $x = 1$.', '$8$', '$7$', '$11$‎‏‎', '$14$', 'option_c', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(4)x + 3 = 8x + 3$.\nEvaluate this derivative at $x = 1$ to find the gradient:\n$m = 8(1) + 3 = 8 + 3 = 11$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a94', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 2x^2 + 5x$ at the point where $x = 3$.', '$14$', '$11$', '$20$', '$17$‎‏‎', 'option_d', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(2)x + 5 = 4x + 5$.\nEvaluate this derivative at $x = 3$ to find the gradient:\n$m = 4(3) + 5 = 12 + 5 = 17$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a82', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 4x^2 + 5x$ at the point where $x = 3$.', '$29$‎‏‎', '$17$', '$26$', '$32$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(4)x + 5 = 8x + 5$.\nEvaluate this derivative at $x = 3$ to find the gradient:\n$m = 8(3) + 5 = 24 + 5 = 29$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a83', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 5x^2 + 3x$ at the point where $x = 1$.', '$13$‎‏‎', '$10$', '$16$', '$8$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(5)x + 3 = 10x + 3$.\nEvaluate this derivative at $x = 1$ to find the gradient:\n$m = 10(1) + 3 = 10 + 3 = 13$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a8c', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 2x^2 + 3x$ at the point where $x = 1$.', '$10$', '$7$‎‏‎', '$4$', '$5$', 'option_b', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(2)x + 3 = 4x + 3$.\nEvaluate this derivative at $x = 1$ to find the gradient:\n$m = 4(1) + 3 = 4 + 3 = 7$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a91', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 3x^2 + 5x$ at the point where $x = 3$.', '$23$‎‏‎', '$26$', '$14$', '$20$', 'option_a', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(3)x + 5 = 6x + 5$.\nEvaluate this derivative at $x = 3$ to find the gradient:\n$m = 6(3) + 5 = 18 + 5 = 23$.', 1);
