INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a84', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 2x^2 + 4x$ at the point where $x = 2$.', '$15$', '$9$', '$8$', '$12$‎‏‎', 'option_d', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(2)x + 4 = 4x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 4(2) + 4 = 8 + 4 = 12$.', 1);
