INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a93', '6a422a4790ab47510c6f7a7f', 'Find the gradient of the curve $y = 5x^2 + 4x$ at the point where $x = 2$.', '$14$', '$21$', '$24$‎‏‎', '$27$', 'option_c', NULL, 'First, differentiate $y$ with respect to $x$:\n$\\frac{dy}{dx} = 2(5)x + 4 = 10x + 4$.\nEvaluate this derivative at $x = 2$ to find the gradient:\n$m = 10(2) + 4 = 20 + 4 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a9a', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(1)$ for $f(x) = 5x^2$.', '$10$‎‏‎', '$8$', '$5$', '$12$', 'option_a', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{5(x+h)^2 - 5x^2}{h} = \\lim_{h \\to 0} \\frac{5(x^2 + 2xh + h^2) - 5x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{10xh + 5h^2}{h} = \\lim_{h \\to 0} (10x + 5h) = 10x$.\nEvaluating at $x = 1$: $f\'(1) = 10(1) = 10$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a9d', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(1)$ for $f(x) = 4x^2$.', '$8$‎‏‎', '$10$', '$6$', '$4$', 'option_a', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{4(x+h)^2 - 4x^2}{h} = \\lim_{h \\to 0} \\frac{4(x^2 + 2xh + h^2) - 4x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{8xh + 4h^2}{h} = \\lim_{h \\to 0} (8x + 4h) = 8x$.\nEvaluating at $x = 1$: $f\'(1) = 8(1) = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7a9e', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(2)$ for $f(x) = 5x^2$.', '$18$', '$20$‎‏‎', '$10$', '$22$', 'option_b', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{5(x+h)^2 - 5x^2}{h} = \\lim_{h \\to 0} \\frac{5(x^2 + 2xh + h^2) - 5x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{10xh + 5h^2}{h} = \\lim_{h \\to 0} (10x + 5h) = 10x$.\nEvaluating at $x = 2$: $f\'(2) = 10(2) = 20$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7aab', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(3)$ for $f(x) = 2x^2$.', '$6$', '$14$', '$10$', '$12$‎‏‎', 'option_d', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{2(x+h)^2 - 2x^2}{h} = \\lim_{h \\to 0} \\frac{2(x^2 + 2xh + h^2) - 2x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{4xh + 2h^2}{h} = \\lim_{h \\to 0} (4x + 2h) = 4x$.\nEvaluating at $x = 3$: $f\'(3) = 4(3) = 12$.', 1);
