INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7aa0', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(1)$ for $f(x) = 3x^2$.', '$3$', '$4$', '$6$‎‏‎', '$8$', 'option_c', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{3(x+h)^2 - 3x^2}{h} = \\lim_{h \\to 0} \\frac{3(x^2 + 2xh + h^2) - 3x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{6xh + 3h^2}{h} = \\lim_{h \\to 0} (6x + 3h) = 6x$.\nEvaluating at $x = 1$: $f\'(1) = 6(1) = 6$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7aa2', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(3)$ for $f(x) = 5x^2$.', '$28$', '$15$', '$30$‎‏‎', '$32$', 'option_c', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{5(x+h)^2 - 5x^2}{h} = \\lim_{h \\to 0} \\frac{5(x^2 + 2xh + h^2) - 5x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{10xh + 5h^2}{h} = \\lim_{h \\to 0} (10x + 5h) = 10x$.\nEvaluating at $x = 3$: $f\'(3) = 10(3) = 30$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4790ab47510c6f7aa8', '6a422a4790ab47510c6f7a96', 'Using differentiation from first principles, find the value of $f\'(3)$ for $f(x) = 3x^2$.', '$18$‎‏‎', '$16$', '$9$', '$20$', 'option_a', NULL, 'Using the first principles limit formula:\n$f\'(x) = \\lim_{h \\to 0} \\frac{3(x+h)^2 - 3x^2}{h} = \\lim_{h \\to 0} \\frac{3(x^2 + 2xh + h^2) - 3x^2}{h}$\n$= \\lim_{h \\to 0} \\frac{6xh + 3h^2}{h} = \\lim_{h \\to 0} (6x + 3h) = 6x$.\nEvaluating at $x = 3$: $f\'(3) = 6(3) = 18$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ab1', '6a422a4890ab47510c6f7aad', 'Using first principles of differentiation, evaluate $g\'(1)$ for the rational function $g(x) = \\frac{20}{x}$.', '$20$', '$-20$‎‏‎', '$-19$', '$-21$', 'option_b', NULL, 'By definition:\n$g\'(x) = \\lim_{h \\to 0} \\frac{\\frac{20}{x+h} - \\frac{20}{x}}{h} = \\lim_{h \\to 0} \\frac{20x - 20(x+h)}{hx(x+h)} = \\lim_{h \\to 0} \\frac{-20h}{hx(x+h)} = \\frac{-20}{x^2}$.\nEvaluating at $x = 1$: $g\'(1) = \\frac{-20}{1^2} = -20$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ab5', '6a422a4890ab47510c6f7aad', 'Using first principles of differentiation, evaluate $g\'(2)$ for the rational function $g(x) = \\frac{20}{x}$.', '$-4$', '$5$', '$-6$', '$-5$‎‏‎', 'option_d', NULL, 'By definition:\n$g\'(x) = \\lim_{h \\to 0} \\frac{\\frac{20}{x+h} - \\frac{20}{x}}{h} = \\lim_{h \\to 0} \\frac{20x - 20(x+h)}{hx(x+h)} = \\lim_{h \\to 0} \\frac{-20h}{hx(x+h)} = \\frac{-20}{x^2}$.\nEvaluating at $x = 2$: $g\'(2) = \\frac{-20}{2^2} = -5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ab8', '6a422a4890ab47510c6f7aad', 'Using first principles of differentiation, evaluate $g\'(2)$ for the rational function $g(x) = \\frac{16}{x}$.', '$4$', '$-5$', '$-4$‎‏‎', '$-3$', 'option_c', NULL, 'By definition:\n$g\'(x) = \\lim_{h \\to 0} \\frac{\\frac{16}{x+h} - \\frac{16}{x}}{h} = \\lim_{h \\to 0} \\frac{16x - 16(x+h)}{hx(x+h)} = \\lim_{h \\to 0} \\frac{-16h}{hx(x+h)} = \\frac{-16}{x^2}$.\nEvaluating at $x = 2$: $g\'(2) = \\frac{-16}{2^2} = -4$.', 1);
