INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ac1', '6a422a4890ab47510c6f7aad', 'Using first principles of differentiation, evaluate $g\'(2)$ for the rational function $g(x) = \\frac{20}{x}$.', '$-5$‎‏‎', '$5$', '$-6$', '$-4$', 'option_a', NULL, 'By definition:\n$g\'(x) = \\lim_{h \\to 0} \\frac{\\frac{20}{x+h} - \\frac{20}{x}}{h} = \\lim_{h \\to 0} \\frac{20x - 20(x+h)}{hx(x+h)} = \\lim_{h \\to 0} \\frac{-20h}{hx(x+h)} = \\frac{-20}{x^2}$.\nEvaluating at $x = 2$: $g\'(2) = \\frac{-20}{2^2} = -5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ac8', '6a422a4890ab47510c6f7ac4', 'Using increment notation, find the average rate of change $\\frac{\\Delta y}{\\Delta x}$ for the function $y = 5x^2$ as $x$ changes from $1$ to $1$.', '$8$', '$12$', '$5$', '$10$‎‏‎', 'option_d', NULL, 'Average rate of change is given by:\n$\\frac{\\Delta y}{\\Delta x} = \\frac{y(1) - y(1)}{1 - 1} = \\frac{5(1)^2 - 5(1)^2}{0}$\n$= \\frac{5 - 5}{0} = \\frac{0}{0} = 10$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7acd', '6a422a4890ab47510c6f7ac4', 'Using increment notation, find the average rate of change $\\frac{\\Delta y}{\\Delta x}$ for the function $y = 2x^2$ as $x$ changes from $1$ to $3$.', '$8$‎‏‎', '$10$', '$6$', '$6$', 'option_a', NULL, 'Average rate of change is given by:\n$\\frac{\\Delta y}{\\Delta x} = \\frac{y(3) - y(1)}{3 - 1} = \\frac{2(3)^2 - 2(1)^2}{2}$\n$= \\frac{18 - 2}{2} = \\frac{16}{2} = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ace', '6a422a4890ab47510c6f7ac4', 'Using increment notation, find the average rate of change $\\frac{\\Delta y}{\\Delta x}$ for the function $y = 3x^2$ as $x$ changes from $1$ to $1$.', '$3$', '$8$', '$4$', '$6$‎‏‎', 'option_d', NULL, 'Average rate of change is given by:\n$\\frac{\\Delta y}{\\Delta x} = \\frac{y(1) - y(1)}{1 - 1} = \\frac{3(1)^2 - 3(1)^2}{0}$\n$= \\frac{3 - 3}{0} = \\frac{0}{0} = 6$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7acf', '6a422a4890ab47510c6f7ac4', 'Using increment notation, find the average rate of change $\\frac{\\Delta y}{\\Delta x}$ for the function $y = 4x^2$ as $x$ changes from $1$ to $2$.', '$10$', '$12$‎‏‎', '$14$', '$8$', 'option_b', NULL, 'Average rate of change is given by:\n$\\frac{\\Delta y}{\\Delta x} = \\frac{y(2) - y(1)}{2 - 1} = \\frac{4(2)^2 - 4(1)^2}{1}$\n$= \\frac{16 - 4}{1} = \\frac{12}{1} = 12$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ad4', '6a422a4890ab47510c6f7ac4', 'Using increment notation, find the average rate of change $\\frac{\\Delta y}{\\Delta x}$ for the function $y = 5x^2$ as $x$ changes from $1$ to $1$.', '$10$‎‏‎', '$12$', '$5$', '$8$', 'option_a', NULL, 'Average rate of change is given by:\n$\\frac{\\Delta y}{\\Delta x} = \\frac{y(1) - y(1)}{1 - 1} = \\frac{5(1)^2 - 5(1)^2}{0}$\n$= \\frac{5 - 5}{0} = \\frac{0}{0} = 10$.', 1);
