INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ade', '6a422a4890ab47510c6f7adb', 'Evaluate the derivative of $y = 4x^4 + 5x^2$ at the point where $x = 1$.', '$22$', '$26$‎‏‎', '$9$', '$30$', 'option_b', NULL, 'Apply the power rule term-by-term:\n$\\frac{dy}{dx} = 4(4)x^3 + 2(5)x = 16x^3 + 10x$.\nSubstitute $x = 1$:\n$\\left.\\frac{dy}{dx}\\right|_{x=1} = 16(1)^3 + 10(1) = 26 = 26$.', 1);
