INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ae4', '6a422a4890ab47510c6f7adb', 'Evaluate the derivative of $y = 2x^4 + 5x^2$ at the point where $x = 1$.', '$7$', '$22$', '$14$', '$18$‎‏‎', 'option_d', NULL, 'Apply the power rule term-by-term:\n$\\frac{dy}{dx} = 4(2)x^3 + 2(5)x = 8x^3 + 10x$.\nSubstitute $x = 1$:\n$\\left.\\frac{dy}{dx}\\right|_{x=1} = 8(1)^3 + 10(1) = 18 = 18$.', 1);
