INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ae6', '6a422a4890ab47510c6f7adb', 'Evaluate the derivative of $y = 4x^4 + 4x^2$ at the point where $x = 1$.', '$24$‎‏‎', '$8$', '$20$', '$28$', 'option_a', NULL, 'Apply the power rule term-by-term:\n$\\frac{dy}{dx} = 4(4)x^3 + 2(4)x = 16x^3 + 8x$.\nSubstitute $x = 1$:\n$\\left.\\frac{dy}{dx}\\right|_{x=1} = 16(1)^3 + 8(1) = 24 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ae7', '6a422a4890ab47510c6f7adb', 'Evaluate the derivative of $y = 5x^4 + 5x^2$ at the point where $x = 1$.', '$10$', '$26$', '$34$', '$30$‎‏‎', 'option_d', NULL, 'Apply the power rule term-by-term:\n$\\frac{dy}{dx} = 4(5)x^3 + 2(5)x = 20x^3 + 10x$.\nSubstitute $x = 1$:\n$\\left.\\frac{dy}{dx}\\right|_{x=1} = 20(1)^3 + 10(1) = 30 = 30$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7ae9', '6a422a4890ab47510c6f7adb', 'Evaluate the derivative of $y = 3x^4 + 4x^2$ at the point where $x = 1$.', '$16$', '$7$', '$24$', '$20$‎‏‎', 'option_d', NULL, 'Apply the power rule term-by-term:\n$\\frac{dy}{dx} = 4(3)x^3 + 2(4)x = 12x^3 + 8x$.\nSubstitute $x = 1$:\n$\\left.\\frac{dy}{dx}\\right|_{x=1} = 12(1)^3 + 8(1) = 20 = 20$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7af6', '6a422a4890ab47510c6f7af2', 'Calculate the derivative of $f(x) = 5e^{3x}$ at $x = 0$.', '$5$', '$18$', '$3$', '$15$‎‏‎', 'option_d', NULL, 'Using the chain rule for exponential functions:\n$f\'(x) = 5 \\times 3e^{3x} = 15e^{3x}$.\nSubstitute $x = 0$:\n$f\'(0) = 15e^0 = 15$.', 1);
