INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7b17', '6a422a4890ab47510c6f7b09', 'Find the derivative of the logarithmic function $y = 6\\ln(4x)$ at $x = 2$.', '$24$', '$3$‎‏‎', '$6$', '$1.5$', 'option_b', NULL, 'Recall that $\\frac{d}{dx}(\\ln(ux)) = \\frac{1}{x}$. Thus:\n$\\frac{dy}{dx} = 6 \\times \\frac{1}{x} = \\frac{6}{x}$.\nEvaluating at $x = 2$ yields $\\frac{6}{2} = 3$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7b0f', '6a422a4890ab47510c6f7b09', 'Find the derivative of the logarithmic function $y = 6\\ln(5x)$ at $x = 3$.', '$2$‎‏‎', '$1$', '$30$', '$4$', 'option_a', NULL, 'Recall that $\\frac{d}{dx}(\\ln(ux)) = \\frac{1}{x}$. Thus:\n$\\frac{dy}{dx} = 6 \\times \\frac{1}{x} = \\frac{6}{x}$.\nEvaluating at $x = 3$ yields $\\frac{6}{3} = 2$.', 1);
