INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4890ab47510c6f7b1b', '6a422a4890ab47510c6f7b09', 'Find the derivative of the logarithmic function $y = 6\\ln(5x)$ at $x = 3$.', '$2$‎‏‎', '$4$', '$30$', '$1$', 'option_a', NULL, 'Recall that $\\frac{d}{dx}(\\ln(ux)) = \\frac{1}{x}$. Thus:\n$\\frac{dy}{dx} = 6 \\times \\frac{1}{x} = \\frac{6}{x}$.\nEvaluating at $x = 3$ yields $\\frac{6}{3} = 2$.', 1);
