INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b23', '6a422a4990ab47510c6f7b20', 'Find the derivative of the trigonometric function $y = 4\\sin(5x)$ at the point $x = 0$.', '$4$', '$-20$', '$0$', '$20$‎‏‎', 'option_d', NULL, 'Differentiating using the trigonometric chain rule:\n$\\frac{dy}{dx} = 4 \\times 5\\cos(5x) = 20\\cos(5x)$.\nSubstitute $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = 20\\cos(0) = 20$.', 1);
