INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b40', '6a422a4990ab47510c6f7b37', 'Evaluate the derivative of $y = \\arcsin(2x)$ at $x = 0$.', '$2$‎‏‎', '$1$', '$0$', '$4$', 'option_a', NULL, 'Using the derivative formula for inverse sine:\n$\\frac{dy}{dx} = \\frac{2}{\\sqrt{1 - (2x)^2}}$.\nSubstitute $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = \\frac{2}{\\sqrt{1 - 0}} = 2$.', 1);
