INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b48', '6a422a4990ab47510c6f7b37', 'Evaluate the derivative of $y = \\arcsin(2x)$ at $x = 0$.', '$1$', '$0$', '$4$', '$2$‎‏‎', 'option_d', NULL, 'Using the derivative formula for inverse sine:\n$\\frac{dy}{dx} = \\frac{2}{\\sqrt{1 - (2x)^2}}$.\nSubstitute $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = \\frac{2}{\\sqrt{1 - 0}} = 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b50', '6a422a4990ab47510c6f7b4e', 'Apply the Chain Rule to evaluate the derivative of $y = (2x + 4)^3$ at $x = 2$.', '$394$', '$369$', '$384$‎‏‎', '$768$', 'option_c', NULL, 'Let $u = 2x + 4$, so $y = u^3$.\nBy Chain Rule:\n$\\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} = 3u^2 \\times 2 = 6(2x + 4)^2$.\nEvaluate at $x = 2$:\n$6(2(2) + 4)^2 = 6(8)^2 = 6(64) = 384$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b52', '6a422a4990ab47510c6f7b4e', 'Apply the Chain Rule to evaluate the derivative of $y = (2x + 3)^3$ at $x = 1$.', '$135$', '$150$‎‏‎', '$300$', '$160$', 'option_b', NULL, 'Let $u = 2x + 3$, so $y = u^3$.\nBy Chain Rule:\n$\\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} = 3u^2 \\times 2 = 6(2x + 3)^2$.\nEvaluate at $x = 1$:\n$6(2(1) + 3)^2 = 6(5)^2 = 6(25) = 150$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b57', '6a422a4990ab47510c6f7b4e', 'Apply the Chain Rule to evaluate the derivative of $y = (2x + 5)^3$ at $x = 3$.', '$1452$', '$736$', '$726$‎‏‎', '$711$', 'option_c', NULL, 'Let $u = 2x + 5$, so $y = u^3$.\nBy Chain Rule:\n$\\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} = 3u^2 \\times 2 = 6(2x + 5)^2$.\nEvaluate at $x = 3$:\n$6(2(3) + 5)^2 = 6(11)^2 = 6(121) = 726$.', 1);
