INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b61', '6a422a4990ab47510c6f7b4e', 'Apply the Chain Rule to evaluate the derivative of $y = (2x + 3)^3$ at $x = 1$.', '$300$', '$160$', '$150$‎‏‎', '$135$', 'option_c', NULL, 'Let $u = 2x + 3$, so $y = u^3$.\nBy Chain Rule:\n$\\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} = 3u^2 \\times 2 = 6(2x + 3)^2$.\nEvaluate at $x = 1$:\n$6(2(1) + 3)^2 = 6(5)^2 = 6(25) = 150$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b70', '6a422a4990ab47510c6f7b65', 'Find the derivative of the product $y = x^{4}e^{4x}$ at $x = 1$. Express your answer in terms of $e^{4}$.', '$e^{4}$', '$8e^{4}$‎‏‎', '$7e^{4}$', '$10e^{4}$', 'option_b', NULL, 'Apply the product rule $\\frac{d}{dx}(uv) = u\'v + uv\'$:\nLet $u = x^{4} \\implies u\' = 4x^{3}$, and $v = e^{4x} \\implies v\' = 4e^{4x}$.\n$$dy/dx = (4x^{3})e^{4x} + (x^{power})(b e^{4x})$$\nSubstitute $x = 1$:\n$dy/dx = (4)e^{4} + (1)(4e^{4}) = (8)e^{4} = 8e^{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b73', '6a422a4990ab47510c6f7b65', 'Find the derivative of the product $y = x^{3}e^{4x}$ at $x = 1$. Express your answer in terms of $e^{4}$.', '$9e^{4}$', '$e^{4}$', '$6e^{4}$', '$7e^{4}$‎‏‎', 'option_d', NULL, 'Apply the product rule $\\frac{d}{dx}(uv) = u\'v + uv\'$:\nLet $u = x^{3} \\implies u\' = 3x^{2}$, and $v = e^{4x} \\implies v\' = 4e^{4x}$.\n$$dy/dx = (3x^{2})e^{4x} + (x^{power})(b e^{4x})$$\nSubstitute $x = 1$:\n$dy/dx = (3)e^{4} + (1)(4e^{4}) = (7)e^{4} = 7e^{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b76', '6a422a4990ab47510c6f7b65', 'Find the derivative of the product $y = x^{2}e^{4x}$ at $x = 1$. Express your answer in terms of $e^{4}$.', '$6e^{4}$‎‏‎', '$5e^{4}$', '$e^{4}$', '$8e^{4}$', 'option_a', NULL, 'Apply the product rule $\\frac{d}{dx}(uv) = u\'v + uv\'$:\nLet $u = x^{2} \\implies u\' = 2x^{1}$, and $v = e^{4x} \\implies v\' = 4e^{4x}$.\n$$dy/dx = (2x^{1})e^{4x} + (x^{power})(b e^{4x})$$\nSubstitute $x = 1$:\n$dy/dx = (2)e^{4} + (1)(4e^{4}) = (6)e^{4} = 6e^{4}$.', 1);
