INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b72', '6a422a4990ab47510c6f7b65', 'Find the derivative of the product $y = x^{2}e^{3x}$ at $x = 1$. Express your answer in terms of $e^{3}$.', '$5e^{3}$‎‏‎', '$4e^{3}$', '$e^{3}$', '$7e^{3}$', 'option_a', NULL, 'Apply the product rule $\\frac{d}{dx}(uv) = u\'v + uv\'$:\nLet $u = x^{2} \\implies u\' = 2x^{1}$, and $v = e^{3x} \\implies v\' = 3e^{3x}$.\n$$dy/dx = (2x^{1})e^{3x} + (x^{power})(b e^{3x})$$\nSubstitute $x = 1$:\n$dy/dx = (2)e^{3} + (1)(3e^{3}) = (5)e^{3} = 5e^{3}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b85', '6a422a4990ab47510c6f7b7c', 'Apply the Quotient Rule to calculate the derivative of $y = \\frac{2x + 5}{x + 2}$ at $x = 0$.', '$-1/2$', '$--1/4$', '$-1/4$‎‏‎', '$1/4$', 'option_c', NULL, 'Let $u = 2x + 5 \\implies u\' = 2$, and $v = x + 2 \\implies v\' = 1$.\nBy Quotient Rule:\n$\\frac{dy}{dx} = \\frac{u\'v - uv\'}{v^2} = \\frac{2(x+2) - (2x+5)(1)}{(x+2)^2} = \\frac{4 - 5}{(x+2)^2}$ at $x=0$.\nSubstitute $x=0$:\n$\\frac{4 - 5}{4} = \\frac{-1}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b86', '6a422a4990ab47510c6f7b7c', 'Apply the Quotient Rule to calculate the derivative of $y = \\frac{3x + 3}{x + 2}$ at $x = 0$.', '$-3/4$', '$5/4$', '$3/4$‎‏‎', '$3/2$', 'option_c', NULL, 'Let $u = 3x + 3 \\implies u\' = 3$, and $v = x + 2 \\implies v\' = 1$.\nBy Quotient Rule:\n$\\frac{dy}{dx} = \\frac{u\'v - uv\'}{v^2} = \\frac{3(x+2) - (3x+3)(1)}{(x+2)^2} = \\frac{6 - 3}{(x+2)^2}$ at $x=0$.\nSubstitute $x=0$:\n$\\frac{6 - 3}{4} = \\frac{3}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b8e', '6a422a4990ab47510c6f7b7c', 'Apply the Quotient Rule to calculate the derivative of $y = \\frac{3x + 5}{x + 2}$ at $x = 0$.', '$3/4$', '$1/4$‎‏‎', '$1/2$', '$-1/4$', 'option_b', NULL, 'Let $u = 3x + 5 \\implies u\' = 3$, and $v = x + 2 \\implies v\' = 1$.\nBy Quotient Rule:\n$\\frac{dy}{dx} = \\frac{u\'v - uv\'}{v^2} = \\frac{3(x+2) - (3x+5)(1)}{(x+2)^2} = \\frac{6 - 5}{(x+2)^2}$ at $x=0$.\nSubstitute $x=0$:\n$\\frac{6 - 5}{4} = \\frac{1}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b90', '6a422a4990ab47510c6f7b7c', 'Apply the Quotient Rule to calculate the derivative of $y = \\frac{5x + 4}{x + 2}$ at $x = 0$.', '$8/4$', '$6/4$‎‏‎', '$-6/4$', '$6/2$', 'option_b', NULL, 'Let $u = 5x + 4 \\implies u\' = 5$, and $v = x + 2 \\implies v\' = 1$.\nBy Quotient Rule:\n$\\frac{dy}{dx} = \\frac{u\'v - uv\'}{v^2} = \\frac{5(x+2) - (5x+4)(1)}{(x+2)^2} = \\frac{10 - 4}{(x+2)^2}$ at $x=0$.\nSubstitute $x=0$:\n$\\frac{10 - 4}{4} = \\frac{6}{4}$.', 1);
