INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b88', '6a422a4990ab47510c6f7b7c', 'Apply the Quotient Rule to calculate the derivative of $y = \\frac{5x + 5}{x + 2}$ at $x = 0$.', '$5/4$‎‏‎', '$-5/4$', '$5/2$', '$7/4$', 'option_a', NULL, 'Let $u = 5x + 5 \\implies u\' = 5$, and $v = x + 2 \\implies v\' = 1$.\nBy Quotient Rule:\n$\\frac{dy}{dx} = \\frac{u\'v - uv\'}{v^2} = \\frac{5(x+2) - (5x+5)(1)}{(x+2)^2} = \\frac{10 - 5}{(x+2)^2}$ at $x=0$.\nSubstitute $x=0$:\n$\\frac{10 - 5}{4} = \\frac{5}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b9e', '6a422a4990ab47510c6f7b93', 'Find the derivative of the combined function $y = e^{4x}\\cos(4x)$ at the point $x = 0$.', '$0$', '$4$', '$4$‎‏‎', '$-4$', 'option_c', NULL, 'Using the product and chain rules:\n$\\frac{dy}{dx} = (\\frac{d}{dx}e^{4x})\\cos(4x) + e^{4x}(\\frac{d}{dx}\\cos(4x)) = 4e^{4x}\\cos(4x) - 4e^{4x}\\sin(4x)$.\nAt $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = 4e^0\\cos(0) - 4e^0\\sin(0) = 4(1)(1) - 0 = 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7b9f', '6a422a4990ab47510c6f7b93', 'Find the derivative of the combined function $y = e^{5x}\\cos(5x)$ at the point $x = 0$.', '$5$‎‏‎', '$0$', '$-5$', '$5$', 'option_a', NULL, 'Using the product and chain rules:\n$\\frac{dy}{dx} = (\\frac{d}{dx}e^{5x})\\cos(5x) + e^{5x}(\\frac{d}{dx}\\cos(5x)) = 5e^{5x}\\cos(5x) - 5e^{5x}\\sin(5x)$.\nAt $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = 5e^0\\cos(0) - 5e^0\\sin(0) = 5(1)(1) - 0 = 5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ba5', '6a422a4990ab47510c6f7b93', 'Find the derivative of the combined function $y = e^{3x}\\cos(5x)$ at the point $x = 0$.', '$3$‎‏‎', '$-3$', '$5$', '$0$', 'option_a', NULL, 'Using the product and chain rules:\n$\\frac{dy}{dx} = (\\frac{d}{dx}e^{3x})\\cos(5x) + e^{3x}(\\frac{d}{dx}\\cos(5x)) = 3e^{3x}\\cos(5x) - 5e^{3x}\\sin(5x)$.\nAt $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = 3e^0\\cos(0) - 5e^0\\sin(0) = 3(1)(1) - 0 = 3$.', 1);
