INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ba3', '6a422a4990ab47510c6f7b93', 'Find the derivative of the combined function $y = e^{5x}\\cos(3x)$ at the point $x = 0$.', '$-5$', '$3$', '$0$', '$5$‎‏‎', 'option_d', NULL, 'Using the product and chain rules:\n$\\frac{dy}{dx} = (\\frac{d}{dx}e^{5x})\\cos(3x) + e^{5x}(\\frac{d}{dx}\\cos(3x)) = 5e^{5x}\\cos(3x) - 3e^{5x}\\sin(3x)$.\nAt $x = 0$:\n$\\left.\\frac{dy}{dx}\\right|_{x=0} = 5e^0\\cos(0) - 3e^0\\sin(0) = 5(1)(1) - 0 = 5$.', 1);
