INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bb2', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 5x^3 + 4x^2$ at the point $x = 1$.', '$32$', '$23$', '$44$', '$38$‎‏‎', 'option_d', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(5)x^2 + 2(4)x = 15x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(5)x + 2(4) = 30x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 30(1) + 8 = 38$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bb5', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 4x^3 + 4x^2$ at the point $x = 1$.', '$20$', '$32$‎‏‎', '$38$', '$26$', 'option_b', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(4)x^2 + 2(4)x = 12x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(4)x + 2(4) = 24x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 24(1) + 8 = 32$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bb9', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 4x^3 + 5x^2$ at the point $x = 1$.', '$28$', '$22$', '$34$‎‏‎', '$40$', 'option_c', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(4)x^2 + 2(5)x = 12x^2 + 10x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(4)x + 2(5) = 24x + 10$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 24(1) + 10 = 34$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bbd', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 4x^3 + 3x^2$ at the point $x = 1$.', '$18$', '$30$‎‏‎', '$36$', '$24$', 'option_b', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(4)x^2 + 2(3)x = 12x^2 + 6x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(4)x + 2(3) = 24x + 6$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 24(1) + 6 = 30$.', 1);
