INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7baf', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 2x^3 + 4x^2$ at the point $x = 1$.', '$26$', '$14$', '$14$', '$20$‎‏‎', 'option_d', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(2)x^2 + 2(4)x = 6x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(2)x + 2(4) = 12x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 12(1) + 8 = 20$.', 1);
