INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bbb', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 2x^3 + 4x^2$ at the point $x = 1$.', '$14$', '$14$', '$26$', '$20$‎‏‎', 'option_d', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(2)x^2 + 2(4)x = 6x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(2)x + 2(4) = 12x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 12(1) + 8 = 20$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bac', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 3x^3 + 4x^2$ at the point $x = 1$.', '$17$', '$20$', '$26$‎‏‎', '$32$', 'option_c', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(3)x^2 + 2(4)x = 9x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(3)x + 2(4) = 18x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 18(1) + 8 = 26$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bad', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 4x^3 + 5x^2$ at the point $x = 1$.', '$34$‎‏‎', '$22$', '$28$', '$40$', 'option_a', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(4)x^2 + 2(5)x = 12x^2 + 10x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(4)x + 2(5) = 24x + 10$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 24(1) + 10 = 34$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bb0', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 3x^3 + 5x^2$ at the point $x = 1$.', '$34$', '$28$‎‏‎', '$22$', '$19$', 'option_b', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(3)x^2 + 2(5)x = 9x^2 + 10x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(3)x + 2(5) = 18x + 10$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 18(1) + 10 = 28$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bb4', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 3x^3 + 3x^2$ at the point $x = 1$.', '$18$', '$30$', '$24$‎‏‎', '$15$', 'option_c', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(3)x^2 + 2(3)x = 9x^2 + 6x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(3)x + 2(3) = 18x + 6$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 18(1) + 6 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bbe', '6a422a4990ab47510c6f7baa', 'Find the second derivative $\\frac{d^2y}{dx^2}$ of the function $y = 5x^3 + 4x^2$ at the point $x = 1$.', '$32$', '$23$', '$44$', '$38$‎‏‎', 'option_d', NULL, 'First derivative:\n$\\frac{dy}{dx} = 3(5)x^2 + 2(4)x = 15x^2 + 8x$.\nSecond derivative:\n$\\frac{d^2y}{dx^2} = 6(5)x + 2(4) = 30x + 8$.\nAt $x = 1$:\n$\\frac{d^2y}{dx^2} = 30(1) + 8 = 38$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bc4', '6a422a4990ab47510c6f7bc1', 'Given the circle $x^2 + y^2 = 34$, find the slope of the tangent line $\\frac{dy}{dx}$ at the point $(3, 5)$ using implicit differentiation.', '$-3/5$‎‏‎', '$5/-3$', '$1$', '$3/5$', 'option_a', NULL, 'Differentiate implicitly with respect to $x$:\n$2x + 2y\\frac{dy}{dx} = 0 \\implies 2y\\frac{dy}{dx} = -2x \\implies \\frac{dy}{dx} = -\\frac{x}{y}$.\nEvaluating at the point $(3, 5)$:\n$\\frac{dy}{dx} = -\\frac{3}{5}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bcc', '6a422a4990ab47510c6f7bc1', 'Given the circle $x^2 + y^2 = 20$, find the slope of the tangent line $\\frac{dy}{dx}$ at the point $(2, 4)$ using implicit differentiation.', '$-2/4$‎‏‎', '$2/4$', '$1$', '$4/-2$', 'option_a', NULL, 'Differentiate implicitly with respect to $x$:\n$2x + 2y\\frac{dy}{dx} = 0 \\implies 2y\\frac{dy}{dx} = -2x \\implies \\frac{dy}{dx} = -\\frac{x}{y}$.\nEvaluating at the point $(2, 4)$:\n$\\frac{dy}{dx} = -\\frac{2}{4}$.', 1);
