INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bdc', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 5x^2y + 3y^2$ evaluated at the point $(2, 3)$.', '$60$‎‏‎', '$64$', '$30$', '$56$', 'option_a', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(5)xy + 0 = 10xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 10(2)(3) = 60$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bde', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 3x^2y + 5y^2$ evaluated at the point $(2, 3)$.', '$40$', '$32$', '$18$', '$36$‎‏‎', 'option_d', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(3)xy + 0 = 6xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 6(2)(3) = 36$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7be6', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 3x^2y + 4y^2$ evaluated at the point $(2, 3)$.', '$40$', '$36$‎‏‎', '$32$', '$18$', 'option_b', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(3)xy + 0 = 6xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 6(2)(3) = 36$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bda', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 3x^2y + 4y^2$ evaluated at the point $(2, 3)$.', '$40$', '$32$', '$18$', '$36$‎‏‎', 'option_d', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(3)xy + 0 = 6xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 6(2)(3) = 36$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bdb', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 4x^2y + 5y^2$ evaluated at the point $(2, 3)$.', '$44$', '$24$', '$52$', '$48$‎‏‎', 'option_d', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(4)xy + 0 = 8xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 8(2)(3) = 48$.', 1);
