INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bed', '6a422a4990ab47510c6f7bd8', 'Compute the first-order partial derivative $\\frac{\\partial f}{\\partial x}$ of the function $f(x,y) = 2x^2y + 5y^2$ evaluated at the point $(2, 3)$.', '$24$‎‏‎', '$28$', '$20$', '$12$', 'option_a', NULL, 'Treat $y$ as a constant and differentiate with respect to $x$:\n$\\frac{\\partial f}{\\partial x} = 2(2)xy + 0 = 4xy$.\nSubstitute $x = 2$ and $y = 3$:\n$\\frac{\\partial f}{\\partial x} = 4(2)(3) = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bf2', '6a422a4990ab47510c6f7bef', 'For the function of two variables $f(x, y) = 4x^2y^3$, evaluate the mixed second-order partial derivative $\\frac{\\partial^2 f}{\\partial x \\partial y}$ at $(1, 1)$.', '$24$‎‏‎', '$30$', '$12$', '$48$', 'option_a', NULL, 'First, find the partial derivative with respect to $y$:\n$\\frac{\\partial f}{\\partial y} = 3(4)x^2y^2 = 12x^2y^2$.\nNow, differentiate that result with respect to $x$:\n$\\frac{\\partial^2 f}{\\partial x \\partial y} = \\frac{\\partial}{\\partial x}(12x^2y^2) = 6(4)xy^2 = 24xy^2$.\nEvaluating at $(1, 1)$: $6(4)(1)(1)^2 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bf6', '6a422a4990ab47510c6f7bef', 'For the function of two variables $f(x, y) = 4x^2y^3$, evaluate the mixed second-order partial derivative $\\frac{\\partial^2 f}{\\partial x \\partial y}$ at $(1, 1)$.', '$30$', '$12$', '$48$', '$24$‎‏‎', 'option_d', NULL, 'First, find the partial derivative with respect to $y$:\n$\\frac{\\partial f}{\\partial y} = 3(4)x^2y^2 = 12x^2y^2$.\nNow, differentiate that result with respect to $x$:\n$\\frac{\\partial^2 f}{\\partial x \\partial y} = \\frac{\\partial}{\\partial x}(12x^2y^2) = 6(4)xy^2 = 24xy^2$.\nEvaluating at $(1, 1)$: $6(4)(1)(1)^2 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7bf8', '6a422a4990ab47510c6f7bef', 'For the function of two variables $f(x, y) = 2x^2y^3$, evaluate the mixed second-order partial derivative $\\frac{\\partial^2 f}{\\partial x \\partial y}$ at $(1, 1)$.', '$12$‎‏‎', '$6$', '$18$', '$24$', 'option_a', NULL, 'First, find the partial derivative with respect to $y$:\n$\\frac{\\partial f}{\\partial y} = 3(2)x^2y^2 = 6x^2y^2$.\nNow, differentiate that result with respect to $x$:\n$\\frac{\\partial^2 f}{\\partial x \\partial y} = \\frac{\\partial}{\\partial x}(6x^2y^2) = 6(2)xy^2 = 12xy^2$.\nEvaluating at $(1, 1)$: $6(2)(1)(1)^2 = 12$.', 1);
