INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c25', '6a422a4990ab47510c6f7c1d', 'Classify the nature of the turning point of $y = x^2 - 10x + 4$.', '$Local Minimum$‎‏‎', '$Point of Inflection$', '$Local Maximum$', '$Saddle Point$', 'option_a', NULL, 'First, differentiate: $\\frac{dy}{dx} = 2x - 10$, which equals $0$ at $x = 5$.\nNow, perform the second derivative test:\n$\\frac{d^2y}{dx^2} = 2$.\nSince the second derivative is positive ($2 > 0$), the stationary point at $x = 5$ represents a local minimum.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c27', '6a422a4990ab47510c6f7c1d', 'Classify the nature of the turning point of $y = x^2 - 6x + 3$.', '$Point of Inflection$', '$Local Maximum$', '$Saddle Point$', '$Local Minimum$‎‏‎', 'option_d', NULL, 'First, differentiate: $\\frac{dy}{dx} = 2x - 6$, which equals $0$ at $x = 3$.\nNow, perform the second derivative test:\n$\\frac{d^2y}{dx^2} = 2$.\nSince the second derivative is positive ($2 > 0$), the stationary point at $x = 3$ represents a local minimum.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c2a', '6a422a4990ab47510c6f7c1d', 'Classify the nature of the turning point of $y = x^2 - 4x + 3$.', '$Local Maximum$', '$Local Minimum$‎‏‎', '$Point of Inflection$', '$Saddle Point$', 'option_b', NULL, 'First, differentiate: $\\frac{dy}{dx} = 2x - 4$, which equals $0$ at $x = 2$.\nNow, perform the second derivative test:\n$\\frac{d^2y}{dx^2} = 2$.\nSince the second derivative is positive ($2 > 0$), the stationary point at $x = 2$ represents a local minimum.', 1);
