INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c37', '6a422a4990ab47510c6f7c34', 'A production cost function is given by $C(q) = 4q^2 + 5q + 150$. Find the Marginal Cost (MC) of producing $5$ units.', '$55$', '$45$‎‏‎', '$90$', '$40$', 'option_b', NULL, 'Marginal Cost is the first derivative of the Cost function with respect to quantity:\n$MC = \\frac{dC}{dq} = 2(4)q + 5 = 8q + 5$.\nEvaluating at $q = 5$:\n$MC(5) = 8(5) + 5 = 40 + 5 = 45$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c3b', '6a422a4990ab47510c6f7c34', 'A production cost function is given by $C(q) = 4q^2 + 3q + 150$. Find the Marginal Cost (MC) of producing $5$ units.', '$38$', '$43$‎‏‎', '$53$', '$86$', 'option_b', NULL, 'Marginal Cost is the first derivative of the Cost function with respect to quantity:\n$MC = \\frac{dC}{dq} = 2(4)q + 3 = 8q + 3$.\nEvaluating at $q = 5$:\n$MC(5) = 8(5) + 3 = 40 + 3 = 43$.', 1);
