INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c40', '6a422a4990ab47510c6f7c34', 'A production cost function is given by $C(q) = 5q^2 + 5q + 150$. Find the Marginal Cost (MC) of producing $5$ units.', '$50$', '$110$', '$55$‎‏‎', '$65$', 'option_c', NULL, 'Marginal Cost is the first derivative of the Cost function with respect to quantity:\n$MC = \\frac{dC}{dq} = 2(5)q + 5 = 10q + 5$.\nEvaluating at $q = 5$:\n$MC(5) = 10(5) + 5 = 50 + 5 = 55$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c45', '6a422a4990ab47510c6f7c34', 'A production cost function is given by $C(q) = 2q^2 + 4q + 150$. Find the Marginal Cost (MC) of producing $5$ units.', '$48$', '$34$', '$24$‎‏‎', '$19$', 'option_c', NULL, 'Marginal Cost is the first derivative of the Cost function with respect to quantity:\n$MC = \\frac{dC}{dq} = 2(2)q + 4 = 4q + 4$.\nEvaluating at $q = 5$:\n$MC(5) = 4(5) + 4 = 20 + 4 = 24$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c46', '6a422a4990ab47510c6f7c34', 'A production cost function is given by $C(q) = 3q^2 + 5q + 150$. Find the Marginal Cost (MC) of producing $5$ units.', '$35$‎‏‎', '$30$', '$70$', '$45$', 'option_a', NULL, 'Marginal Cost is the first derivative of the Cost function with respect to quantity:\n$MC = \\frac{dC}{dq} = 2(3)q + 5 = 6q + 5$.\nEvaluating at $q = 5$:\n$MC(5) = 6(5) + 5 = 30 + 5 = 35$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c4f', '6a422a4990ab47510c6f7c4b', 'A farmer wants to construct a rectangular enclosure using a straight brick wall as one of the boundaries. If they have $40$ meters of fencing available for the other three sides, find the maximum area they can enclose.', '$400 m²$', '$200 m²$‎‏‎', '$150 m²$', '$300 m²$', 'option_b', NULL, 'Let the sides perpendicular to the wall be $x$, and the parallel side be $y$.\nWe are given $2x + y = 40 \\implies y = 40 - 2x$.\nArea $A = x \\times y = x(40 - 2x) = 40x - 2x^2$.\nTo maximize, differentiate and set to $0$:\n$\\frac{dA}{dx} = 40 - 4x = 0 \\implies x = 10$.\nSubstitute back into Area:\n$A = (10)(40 - 2(10)) = \\frac{40^2}{8} = 200$ m².', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c4d', '6a422a4990ab47510c6f7c4b', 'A farmer wants to construct a rectangular enclosure using a straight brick wall as one of the boundaries. If they have $24$ meters of fencing available for the other three sides, find the maximum area they can enclose.', '$144 m²$', '$172 m²$', '$22 m²$', '$72 m²$‎‏‎', 'option_d', NULL, 'Let the sides perpendicular to the wall be $x$, and the parallel side be $y$.\nWe are given $2x + y = 24 \\implies y = 24 - 2x$.\nArea $A = x \\times y = x(24 - 2x) = 24x - 2x^2$.\nTo maximize, differentiate and set to $0$:\n$\\frac{dA}{dx} = 24 - 4x = 0 \\implies x = 6$.\nSubstitute back into Area:\n$A = (6)(24 - 2(6)) = \\frac{24^2}{8} = 72$ m².', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c4e', '6a422a4990ab47510c6f7c4b', 'A farmer wants to construct a rectangular enclosure using a straight brick wall as one of the boundaries. If they have $32$ meters of fencing available for the other three sides, find the maximum area they can enclose.', '$256 m²$', '$228 m²$', '$78 m²$', '$128 m²$‎‏‎', 'option_d', NULL, 'Let the sides perpendicular to the wall be $x$, and the parallel side be $y$.\nWe are given $2x + y = 32 \\implies y = 32 - 2x$.\nArea $A = x \\times y = x(32 - 2x) = 32x - 2x^2$.\nTo maximize, differentiate and set to $0$:\n$\\frac{dA}{dx} = 32 - 4x = 0 \\implies x = 8$.\nSubstitute back into Area:\n$A = (8)(32 - 2(8)) = \\frac{32^2}{8} = 128$ m².', 1);
