INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c60', '6a422a4990ab47510c6f7c4b', 'A farmer wants to construct a rectangular enclosure using a straight brick wall as one of the boundaries. If they have $16$ meters of fencing available for the other three sides, find the maximum area they can enclose.', '$64 m²$', '$132 m²$', '$-18 m²$', '$32 m²$‎‏‎', 'option_d', NULL, 'Let the sides perpendicular to the wall be $x$, and the parallel side be $y$.\nWe are given $2x + y = 16 \\implies y = 16 - 2x$.\nArea $A = x \\times y = x(16 - 2x) = 16x - 2x^2$.\nTo maximize, differentiate and set to $0$:\n$\\frac{dA}{dx} = 16 - 4x = 0 \\implies x = 4$.\nSubstitute back into Area:\n$A = (4)(16 - 2(4)) = \\frac{16^2}{8} = 32$ m².', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c64', '6a422a4990ab47510c6f7c62', 'Use L\'Hopital\'s Rule to evaluate the limit: $\\lim_{x \\to 0} \\frac{1 - \\cos(3x)}{x^2}$.', '$0$', '$3$', '$9/2$‎‏‎', '$9$', 'option_c', NULL, 'Direct substitution gives $\\frac{0}{0}$ (indeterminate form). Apply L\'Hopital\'s Rule by differentiating numerator and denominator:\n$\\lim_{x \\to 0} \\frac{3\\sin(3x)}{2x}$.\nSubstituting again still gives $\\frac{0}{0}$. Apply L\'Hopital\'s Rule a second time:\n$\\lim_{x \\to 0} \\frac{9\\cos(3x)}{2} = \\frac{9(1)}{2} = \\frac{9}{2}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c6d', '6a422a4990ab47510c6f7c62', 'Use L\'Hopital\'s Rule to evaluate the limit: $\\lim_{x \\to 0} \\frac{1 - \\cos(4x)}{x^2}$.', '$4$', '$16$', '$16/2$‎‏‎', '$0$', 'option_c', NULL, 'Direct substitution gives $\\frac{0}{0}$ (indeterminate form). Apply L\'Hopital\'s Rule by differentiating numerator and denominator:\n$\\lim_{x \\to 0} \\frac{4\\sin(4x)}{2x}$.\nSubstituting again still gives $\\frac{0}{0}$. Apply L\'Hopital\'s Rule a second time:\n$\\lim_{x \\to 0} \\frac{16\\cos(4x)}{2} = \\frac{16(1)}{2} = \\frac{16}{2}$.', 1);
