INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c7b', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 3x + 4$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$23$', '$15$', '$38$', '$19$‎‏‎', 'option_d', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (3x + 4) dx = \\frac{3}{2}x^2 + 4x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{3}{2}x^2 + 4x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{3}{2}(4) + 4(2) + 5 = 6 + 8 + 5 = 19$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c81', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 5x + 4$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$46$', '$27$', '$23$‎‏‎', '$19$', 'option_c', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (5x + 4) dx = \\frac{5}{2}x^2 + 4x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{5}{2}x^2 + 4x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{5}{2}(4) + 4(2) + 5 = 10 + 8 + 5 = 23$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c84', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 4x + 4$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$25$', '$17$', '$21$‎‏‎', '$42$', 'option_c', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (4x + 4) dx = \\frac{4}{2}x^2 + 4x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{4}{2}x^2 + 4x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{4}{2}(4) + 4(2) + 5 = 8 + 8 + 5 = 21$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c85', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 5x + 5$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$29$', '$50$', '$21$', '$25$‎‏‎', 'option_d', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (5x + 5) dx = \\frac{5}{2}x^2 + 5x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{5}{2}x^2 + 5x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{5}{2}(4) + 5(2) + 5 = 10 + 10 + 5 = 25$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c88', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 4x + 5$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$23$‎‏‎', '$19$', '$27$', '$46$', 'option_a', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (4x + 5) dx = \\frac{4}{2}x^2 + 5x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{4}{2}x^2 + 5x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{4}{2}(4) + 5(2) + 5 = 8 + 10 + 5 = 23$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c8b', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 3x + 5$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$17$', '$25$', '$21$‎‏‎', '$42$', 'option_c', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (3x + 5) dx = \\frac{3}{2}x^2 + 5x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{3}{2}x^2 + 5x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{3}{2}(4) + 5(2) + 5 = 6 + 10 + 5 = 21$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c7c', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 4x + 5$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$46$', '$19$', '$27$', '$23$‎‏‎', 'option_d', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (4x + 5) dx = \\frac{4}{2}x^2 + 5x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{4}{2}x^2 + 5x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{4}{2}(4) + 5(2) + 5 = 8 + 10 + 5 = 23$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c86', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 2x + 3$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$15$‎‏‎', '$19$', '$30$', '$11$', 'option_a', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (2x + 3) dx = \\frac{2}{2}x^2 + 3x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{2}{2}x^2 + 3x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{2}{2}(4) + 3(2) + 5 = 4 + 6 + 5 = 15$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c87', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 3x + 4$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$38$', '$23$', '$19$‎‏‎', '$15$', 'option_c', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (3x + 4) dx = \\frac{3}{2}x^2 + 4x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{3}{2}x^2 + 4x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{3}{2}(4) + 4(2) + 5 = 6 + 8 + 5 = 19$.', 1);
