INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c8d', '6a422a4990ab47510c6f7c79', 'Solve the differential equation $\\frac{dy}{dx} = 5x + 4$ subject to the initial condition $y(0) = 5$. Find the value of $y(2)$.', '$23$‎‏‎', '$46$', '$19$', '$27$', 'option_a', NULL, 'Integrate both sides with respect to $x$:\n$y(x) = \\int (5x + 4) dx = \\frac{5}{2}x^2 + 4x + C$.\nUsing the initial condition $y(0) = 5$, we find $C = 5$.\nThus, $y(x) = \\frac{5}{2}x^2 + 4x + 5$.\nEvaluating at $x = 2$:\n$y(2) = \\frac{5}{2}(4) + 4(2) + 5 = 10 + 8 + 5 = 23$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c92', '6a422a4990ab47510c6f7c90', 'Find the coefficient of $x^2$ in the Maclaurin series expansion of the function $f(x) = \\cos(3x)$.', '$9/2$', '$-3/2$', '$-9/2$‎‏‎', '$0$', 'option_c', NULL, 'Recall that the Maclaurin series of $\\cos(u) = 1 - \\frac{u^2}{2!} + \\frac{u^4}{4!} - \\dots$\nSubstitute $u = 3x$:\n$\\cos(3x) = 1 - \\frac{(3x)^2}{2} + \\dots = 1 - \\frac{9}{2}x^2 + \\dots$\nThus, the coefficient of $x^2$ is $-\\frac{9}{2}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7c97', '6a422a4990ab47510c6f7c90', 'Find the coefficient of $x^2$ in the Maclaurin series expansion of the function $f(x) = \\cos(4x)$.', '$16/2$', '$0$', '$-4/2$', '$-16/2$‎‏‎', 'option_d', NULL, 'Recall that the Maclaurin series of $\\cos(u) = 1 - \\frac{u^2}{2!} + \\frac{u^4}{4!} - \\dots$\nSubstitute $u = 4x$:\n$\\cos(4x) = 1 - \\frac{(4x)^2}{2} + \\dots = 1 - \\frac{16}{2}x^2 + \\dots$\nThus, the coefficient of $x^2$ is $-\\frac{16}{2}$.', 1);
