INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cb5', '6a422a4990ab47510c6f7ca7', 'Evaluate the indefinite integral: $\\int (9x^2 + 4) dx$.', '$6x^3 + 4x + C$', '$3x^3 + 4x + C$‎‏‎', '$3x^3 + C$', '$9x^3 + 4x + C$', 'option_b', NULL, 'Integrate each term using the reverse power rule:\n$\\int (9x^2 + 4) dx = \\frac{9}{3}x^3 + 4x + C = 3x^3 + 4x + C$.', 1);
