INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cc1', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 12x^2 dx$.', '$36$', '$28$', '$16$', '$32$‎‏‎', 'option_d', NULL, 'First, find the antiderivative of 12$x^2$:\n$F(x) = \\int 12x^2 dx = 4x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 4x^3 \\right]_{0}^{2} = 4(2)^3 - 4(0)^3 = 32 = 32$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ccd', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 12x^2 dx$.', '$28$', '$16$', '$36$', '$32$‎‏‎', 'option_d', NULL, 'First, find the antiderivative of 12$x^2$:\n$F(x) = \\int 12x^2 dx = 4x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 4x^3 \\right]_{0}^{2} = 4(2)^3 - 4(0)^3 = 32 = 32$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cd1', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 12x^2 dx$.', '$28$', '$16$', '$36$', '$32$‎‏‎', 'option_d', NULL, 'First, find the antiderivative of 12$x^2$:\n$F(x) = \\int 12x^2 dx = 4x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 4x^3 \\right]_{0}^{2} = 4(2)^3 - 4(0)^3 = 32 = 32$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cc2', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 15x^2 dx$.', '$36$', '$20$', '$44$', '$40$‎‏‎', 'option_d', NULL, 'First, find the antiderivative of 15$x^2$:\n$F(x) = \\int 15x^2 dx = 5x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 5x^3 \\right]_{0}^{2} = 5(2)^3 - 5(0)^3 = 40 = 40$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cc7', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 6x^2 dx$.', '$8$', '$12$', '$16$‎‏‎', '$20$', 'option_c', NULL, 'First, find the antiderivative of 6$x^2$:\n$F(x) = \\int 6x^2 dx = 2x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 2x^3 \\right]_{0}^{2} = 2(2)^3 - 2(0)^3 = 16 = 16$.', 1);
