INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ccb', '6a422a4990ab47510c6f7cbe', 'Evaluate the definite integral using the Fundamental Theorem of Calculus: $\\int_{0}^{2} 6x^2 dx$.', '$12$', '$20$', '$8$', '$16$‎‏‎', 'option_d', NULL, 'First, find the antiderivative of 6$x^2$:\n$F(x) = \\int 6x^2 dx = 2x^3$.\nBy the Fundamental Theorem of Calculus, evaluate from $0$ to $2$:\n$\\left[ 2x^3 \\right]_{0}^{2} = 2(2)^3 - 2(0)^3 = 16 = 16$.', 1);
