INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cdf', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 21$ and $\\int_{1}^{3} f(x) dx = 13$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$21$', '$34$', '$13$', '$8$‎‏‎', 'option_d', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$21 = 13 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 21 - 13 = 8$.', 1);
