INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cdd', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 19$ and $\\int_{1}^{3} f(x) dx = 11$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$30$', '$11$', '$8$‎‏‎', '$19$', 'option_c', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$19 = 11 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 19 - 11 = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cd9', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 15$ and $\\int_{1}^{3} f(x) dx = 7$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$8$‎‏‎', '$22$', '$15$', '$7$', 'option_a', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$15 = 7 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 15 - 7 = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cda', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 16$ and $\\int_{1}^{3} f(x) dx = 8$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$8$‎‏‎', '$8$', '$24$', '$16$', 'option_a', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$16 = 8 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 16 - 8 = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ce8', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 30$ and $\\int_{1}^{3} f(x) dx = 22$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$52$', '$22$', '$8$‎‏‎', '$30$', 'option_c', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$30 = 22 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 30 - 22 = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7ce9', '6a422a4990ab47510c6f7cd5', 'Given that $\\int_{1}^{5} f(x) dx = 31$ and $\\int_{1}^{3} f(x) dx = 23$, evaluate the definite integral $\\int_{3}^{5} f(x) dx$.', '$54$', '$8$‎‏‎', '$23$', '$31$', 'option_b', NULL, 'Using the interval additive property of definite integrals:\n$\\int_{1}^{5} f(x) dx = \\int_{1}^{3} f(x) dx + \\int_{3}^{5} f(x) dx$.\nSubstitute the known values:\n$31 = 23 + \\int_{3}^{5} f(x) dx \\implies \\int_{3}^{5} f(x) dx = 31 - 23 = 8$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cf0', '6a422a4990ab47510c6f7cec', 'Evaluate the definite integral of the polynomial: $\\int_{1}^{2} (10x + 3) dx$.', '$16$', '$36$', '$20$', '$18$‎‏‎', 'option_d', NULL, 'Find the antiderivative:\n$F(x) = \\frac{10}{2}x^2 + 3x = 5x^2 + 3x$.\nNow evaluate the integral from $1$ to $2$:\n$F(2) - F(1) = (5(2^2) + 3(2)) - (5(1^2) + 3(1))$\n$= (20 + 6) - (5 + 3) = 15 + 3 = 18$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cf1', '6a422a4990ab47510c6f7cec', 'Evaluate the definite integral of the polynomial: $\\int_{1}^{2} (4x + 4) dx$.', '$12$', '$8$', '$10$‎‏‎', '$20$', 'option_c', NULL, 'Find the antiderivative:\n$F(x) = \\frac{4}{2}x^2 + 4x = 2x^2 + 4x$.\nNow evaluate the integral from $1$ to $2$:\n$F(2) - F(1) = (2(2^2) + 4(2)) - (2(1^2) + 4(1))$\n$= (8 + 8) - (2 + 4) = 6 + 4 = 10$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cf3', '6a422a4990ab47510c6f7cec', 'Evaluate the definite integral of the polynomial: $\\int_{1}^{2} (8x + 3) dx$.', '$15$‎‏‎', '$30$', '$13$', '$17$', 'option_a', NULL, 'Find the antiderivative:\n$F(x) = \\frac{8}{2}x^2 + 3x = 4x^2 + 3x$.\nNow evaluate the integral from $1$ to $2$:\n$F(2) - F(1) = (4(2^2) + 3(2)) - (4(1^2) + 3(1))$\n$= (16 + 6) - (4 + 3) = 12 + 3 = 15$.', 1);
