INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cf9', '6a422a4990ab47510c6f7cec', 'Evaluate the definite integral of the polynomial: $\\int_{1}^{2} (4x + 3) dx$.', '$7$', '$9$‎‏‎', '$11$', '$18$', 'option_b', NULL, 'Find the antiderivative:\n$F(x) = \\frac{4}{2}x^2 + 3x = 2x^2 + 3x$.\nNow evaluate the integral from $1$ to $2$:\n$F(2) - F(1) = (2(2^2) + 3(2)) - (2(1^2) + 3(1))$\n$= (8 + 6) - (2 + 3) = 6 + 3 = 9$.', 1);
