INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7cf5', '6a422a4990ab47510c6f7cec', 'Evaluate the definite integral of the polynomial: $\\int_{1}^{2} (4x + 5) dx$.', '$13$', '$22$', '$9$', '$11$‎‏‎', 'option_d', NULL, 'Find the antiderivative:\n$F(x) = \\frac{4}{2}x^2 + 5x = 2x^2 + 5x$.\nNow evaluate the integral from $1$ to $2$:\n$F(2) - F(1) = (2(2^2) + 5(2)) - (2(1^2) + 5(1))$\n$= (8 + 10) - (2 + 5) = 6 + 5 = 11$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d07', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 3)^3 dx$.', '$179/4$', '$175/2$', '$171/4$', '$175/4$‎‏‎', 'option_d', NULL, 'Let $u = x + 3 \\implies du = dx$.\nWhen $x = 0, u = 3$. When $x = 1, u = 4$.\nIntegrate in terms of $u$:\n$\\int_{3}^{4} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{3}^{4} = \\frac{(4)^4 - 3^4}{4} = \\frac{175}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d0a', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 3)^3 dx$.', '$175/2$', '$175/4$‎‏‎', '$171/4$', '$179/4$', 'option_b', NULL, 'Let $u = x + 3 \\implies du = dx$.\nWhen $x = 0, u = 3$. When $x = 1, u = 4$.\nIntegrate in terms of $u$:\n$\\int_{3}^{4} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{3}^{4} = \\frac{(4)^4 - 3^4}{4} = \\frac{175}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d0c', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 5)^3 dx$.', '$667/4$', '$671/4$‎‏‎', '$671/2$', '$675/4$', 'option_b', NULL, 'Let $u = x + 5 \\implies du = dx$.\nWhen $x = 0, u = 5$. When $x = 1, u = 6$.\nIntegrate in terms of $u$:\n$\\int_{5}^{6} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{5}^{6} = \\frac{(6)^4 - 5^4}{4} = \\frac{671}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d0e', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 4)^3 dx$.', '$369/2$', '$369/4$‎‏‎', '$373/4$', '$365/4$', 'option_b', NULL, 'Let $u = x + 4 \\implies du = dx$.\nWhen $x = 0, u = 4$. When $x = 1, u = 5$.\nIntegrate in terms of $u$:\n$\\int_{4}^{5} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{4}^{5} = \\frac{(5)^4 - 4^4}{4} = \\frac{369}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d0f', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 5)^3 dx$.', '$671/2$', '$667/4$', '$671/4$‎‏‎', '$675/4$', 'option_c', NULL, 'Let $u = x + 5 \\implies du = dx$.\nWhen $x = 0, u = 5$. When $x = 1, u = 6$.\nIntegrate in terms of $u$:\n$\\int_{5}^{6} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{5}^{6} = \\frac{(6)^4 - 5^4}{4} = \\frac{671}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d10', '6a422a4990ab47510c6f7d03', 'Evaluate the definite integral using substitution: $\\int_{0}^{1} (x + 3)^3 dx$.', '$179/4$', '$175/4$‎‏‎', '$171/4$', '$175/2$', 'option_b', NULL, 'Let $u = x + 3 \\implies du = dx$.\nWhen $x = 0, u = 3$. When $x = 1, u = 4$.\nIntegrate in terms of $u$:\n$\\int_{3}^{4} u^3 du = \\left[ \\frac{u^4}{4} \\right]_{3}^{4} = \\frac{(4)^4 - 3^4}{4} = \\frac{175}{4}$.', 1);
