INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d1c', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx$.', '$3\\ln(2)$‎‏‎', '$6\\ln(2)$', '$3\\ln(3)$', '$\\ln(2)$', 'option_a', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx = 3 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 3 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 3(\\ln(2) - \\ln(1)) = 3\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d20', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx$.', '$3\\ln(3)$', '$3\\ln(2)$‎‏‎', '$6\\ln(2)$', '$\\ln(2)$', 'option_b', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx = 3 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 3 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 3(\\ln(2) - \\ln(1)) = 3\\ln(2)$.', 1);
