INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d1f', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{4x}{x^2 + 1} dx$.', '$4\\ln(2)$', '$2\\ln(3)$', '$\\ln(2)$', '$2\\ln(2)$‎‏‎', 'option_d', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{4x}{x^2 + 1} dx = 2 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 2 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 2(\\ln(2) - \\ln(1)) = 2\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d24', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx$.', '$6\\ln(2)$', '$\\ln(2)$', '$3\\ln(3)$', '$3\\ln(2)$‎‏‎', 'option_d', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{6x}{x^2 + 1} dx = 3 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 3 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 3(\\ln(2) - \\ln(1)) = 3\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d25', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{8x}{x^2 + 1} dx$.', '$4\\ln(3)$', '$8\\ln(2)$', '$\\ln(2)$', '$4\\ln(2)$‎‏‎', 'option_d', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{8x}{x^2 + 1} dx = 4 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 4 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 4(\\ln(2) - \\ln(1)) = 4\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d2a', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{10x}{x^2 + 1} dx$.', '$5\\ln(3)$', '$5\\ln(2)$‎‏‎', '$\\ln(2)$', '$10\\ln(2)$', 'option_b', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{10x}{x^2 + 1} dx = 5 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 5 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 5(\\ln(2) - \\ln(1)) = 5\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d2b', '6a422a4990ab47510c6f7d1a', 'Evaluate the transcendental definite integral: $\\int_{0}^{1} \\frac{4x}{x^2 + 1} dx$.', '$\\ln(2)$', '$4\\ln(2)$', '$2\\ln(3)$', '$2\\ln(2)$‎‏‎', 'option_d', NULL, 'Let $u = x^2 + 1 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} \\frac{4x}{x^2 + 1} dx = 2 \\int_{0}^{1} \\frac{2x}{x^2 + 1} dx = 2 \\left[ \\ln(x^2 + 1) \\right]_{0}^{1}$\n$= 2(\\ln(2) - \\ln(1)) = 2\\ln(2)$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d35', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+5)(x+8)} dx$.', '$\\ln|x+5| - \\ln|x+8| + C$', '$1/3 \\ln|x+5| + C$', '$1/2 \\ln|x+5| + C$', '$1/3 \\ln|x+5| - 1/3 \\ln|x+8| + C$‎‏‎', 'option_d', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+5)(x+8)} = \\frac{A}{x+5} + \\frac{B}{x+8}$.\nSolving gives $A = \\frac{1}{3}$, $B = -\\frac{1}{3}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/3}{x+5} - \\frac{1/3}{x+8} \\right) dx = \\frac{1}{3}\\ln|x+5| - \\frac{1}{3}\\ln|x+8| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d3e', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+2)(x+5)} dx$.', '$\\ln|x+2| - \\ln|x+5| + C$', '$1/3 \\ln|x+2| - 1/3 \\ln|x+5| + C$‎‏‎', '$1/2 \\ln|x+2| + C$', '$1/3 \\ln|x+2| + C$', 'option_b', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+2)(x+5)} = \\frac{A}{x+2} + \\frac{B}{x+5}$.\nSolving gives $A = \\frac{1}{3}$, $B = -\\frac{1}{3}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/3}{x+2} - \\frac{1/3}{x+5} \\right) dx = \\frac{1}{3}\\ln|x+2| - \\frac{1}{3}\\ln|x+5| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d40', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+4)(x+9)} dx$.', '$1/5 \\ln|x+4| + C$', '$\\ln|x+4| - \\ln|x+9| + C$', '$1/2 \\ln|x+4| + C$', '$1/5 \\ln|x+4| - 1/5 \\ln|x+9| + C$‎‏‎', 'option_d', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+4)(x+9)} = \\frac{A}{x+4} + \\frac{B}{x+9}$.\nSolving gives $A = \\frac{1}{5}$, $B = -\\frac{1}{5}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/5}{x+4} - \\frac{1/5}{x+9} \\right) dx = \\frac{1}{5}\\ln|x+4| - \\frac{1}{5}\\ln|x+9| + C$.', 1);
