INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d3a', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+2)(x+7)} dx$.', '$\\ln|x+2| - \\ln|x+7| + C$', '$1/5 \\ln|x+2| - 1/5 \\ln|x+7| + C$‎‏‎', '$1/5 \\ln|x+2| + C$', '$1/2 \\ln|x+2| + C$', 'option_b', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+2)(x+7)} = \\frac{A}{x+2} + \\frac{B}{x+7}$.\nSolving gives $A = \\frac{1}{5}$, $B = -\\frac{1}{5}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/5}{x+2} - \\frac{1/5}{x+7} \\right) dx = \\frac{1}{5}\\ln|x+2| - \\frac{1}{5}\\ln|x+7| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d3d', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+5)(x+10)} dx$.', '$1/5 \\ln|x+5| - 1/5 \\ln|x+10| + C$‎‏‎', '$1/5 \\ln|x+5| + C$', '$1/2 \\ln|x+5| + C$', '$\\ln|x+5| - \\ln|x+10| + C$', 'option_a', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+5)(x+10)} = \\frac{A}{x+5} + \\frac{B}{x+10}$.\nSolving gives $A = \\frac{1}{5}$, $B = -\\frac{1}{5}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/5}{x+5} - \\frac{1/5}{x+10} \\right) dx = \\frac{1}{5}\\ln|x+5| - \\frac{1}{5}\\ln|x+10| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d3f', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+3)(x+7)} dx$.', '$\\ln|x+3| - \\ln|x+7| + C$', '$1/4 \\ln|x+3| + C$', '$1/2 \\ln|x+3| + C$', '$1/4 \\ln|x+3| - 1/4 \\ln|x+7| + C$‎‏‎', 'option_d', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+3)(x+7)} = \\frac{A}{x+3} + \\frac{B}{x+7}$.\nSolving gives $A = \\frac{1}{4}$, $B = -\\frac{1}{4}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/4}{x+3} - \\frac{1/4}{x+7} \\right) dx = \\frac{1}{4}\\ln|x+3| - \\frac{1}{4}\\ln|x+7| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d41', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+5)(x+8)} dx$.', '$1/3 \\ln|x+5| + C$', '$1/2 \\ln|x+5| + C$', '$1/3 \\ln|x+5| - 1/3 \\ln|x+8| + C$‎‏‎', '$\\ln|x+5| - \\ln|x+8| + C$', 'option_c', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+5)(x+8)} = \\frac{A}{x+5} + \\frac{B}{x+8}$.\nSolving gives $A = \\frac{1}{3}$, $B = -\\frac{1}{3}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/3}{x+5} - \\frac{1/3}{x+8} \\right) dx = \\frac{1}{3}\\ln|x+5| - \\frac{1}{3}\\ln|x+8| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d42', '6a422a4990ab47510c6f7d31', 'Find the indefinite integral: $\\int \\frac{1}{(x+2)(x+6)} dx$.', '$1/2 \\ln|x+2| + C$', '$1/4 \\ln|x+2| - 1/4 \\ln|x+6| + C$‎‏‎', '$1/4 \\ln|x+2| + C$', '$\\ln|x+2| - \\ln|x+6| + C$', 'option_b', NULL, 'Use partial fractions to split the integrand:\n$\\frac{1}{(x+2)(x+6)} = \\frac{A}{x+2} + \\frac{B}{x+6}$.\nSolving gives $A = \\frac{1}{4}$, $B = -\\frac{1}{4}$.\nIntegrate both terms:\n$\\int \\left( \\frac{1/4}{x+2} - \\frac{1/4}{x+6} \\right) dx = \\frac{1}{4}\\ln|x+2| - \\frac{1}{4}\\ln|x+6| + C$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d4d', '6a422a4990ab47510c6f7d48', 'Evaluate the definite trigonometric integral: $\\int_{0}^{\\pi/2} 2\\sin(x) dx$.', '$2$‎‏‎', '$-2$', '$1$', '$0$', 'option_a', NULL, 'The antiderivative of $\\sin(x)$ is $-\\cos(x)$. Therefore:\n$\\int_{0}^{\\pi/2} 2\\sin(x) dx = \\left[ -2\\cos(x) \\right]_{0}^{\\pi/2} = -2\\cos(\\pi/2) - (-2\\cos(0))$\n$= 0 + 2(1) = 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d4f', '6a422a4990ab47510c6f7d48', 'Evaluate the definite trigonometric integral: $\\int_{0}^{\\pi/2} 4\\sin(x) dx$.', '$0$', '$-4$', '$4$‎‏‎', '$1$', 'option_c', NULL, 'The antiderivative of $\\sin(x)$ is $-\\cos(x)$. Therefore:\n$\\int_{0}^{\\pi/2} 4\\sin(x) dx = \\left[ -4\\cos(x) \\right]_{0}^{\\pi/2} = -4\\cos(\\pi/2) - (-4\\cos(0))$\n$= 0 + 4(1) = 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d56', '6a422a4990ab47510c6f7d48', 'Evaluate the definite trigonometric integral: $\\int_{0}^{\\pi/2} 3\\sin(x) dx$.', '$3$‎‏‎', '$-3$', '$0$', '$1$', 'option_a', NULL, 'The antiderivative of $\\sin(x)$ is $-\\cos(x)$. Therefore:\n$\\int_{0}^{\\pi/2} 3\\sin(x) dx = \\left[ -3\\cos(x) \\right]_{0}^{\\pi/2} = -3\\cos(\\pi/2) - (-3\\cos(0))$\n$= 0 + 3(1) = 3$.', 1);
