INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4990ab47510c6f7d5c', '6a422a4990ab47510c6f7d48', 'Evaluate the definite trigonometric integral: $\\int_{0}^{\\pi/2} 5\\sin(x) dx$.', '$0$', '$1$', '$-5$', '$5$‎‏‎', 'option_d', NULL, 'The antiderivative of $\\sin(x)$ is $-\\cos(x)$. Therefore:\n$\\int_{0}^{\\pi/2} 5\\sin(x) dx = \\left[ -5\\cos(x) \\right]_{0}^{\\pi/2} = -5\\cos(\\pi/2) - (-5\\cos(0))$\n$= 0 + 5(1) = 5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d67', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 10\\sin^2(x) dx$.', '$5\\pi$‎‏‎', '$5\\pi/2$', '$10\\pi$', '$\\pi$', 'option_a', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 10\\sin^2(x) dx = \\int_{0}^{\\pi} 5(1 - \\cos(2x)) dx = 5 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 5 \\left( (\\pi - 0) - (0 - 0) \\right) = 5\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d6b', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 10\\sin^2(x) dx$.', '$5\\pi/2$', '$5\\pi$‎‏‎', '$10\\pi$', '$\\pi$', 'option_b', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 10\\sin^2(x) dx = \\int_{0}^{\\pi} 5(1 - \\cos(2x)) dx = 5 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 5 \\left( (\\pi - 0) - (0 - 0) \\right) = 5\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d6c', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 4\\sin^2(x) dx$.', '$\\pi$', '$4\\pi$', '$2\\pi/2$', '$2\\pi$‎‏‎', 'option_d', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 4\\sin^2(x) dx = \\int_{0}^{\\pi} 2(1 - \\cos(2x)) dx = 2 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 2 \\left( (\\pi - 0) - (0 - 0) \\right) = 2\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d70', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 4\\sin^2(x) dx$.', '$2\\pi/2$', '$4\\pi$', '$2\\pi$‎‏‎', '$\\pi$', 'option_c', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 4\\sin^2(x) dx = \\int_{0}^{\\pi} 2(1 - \\cos(2x)) dx = 2 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 2 \\left( (\\pi - 0) - (0 - 0) \\right) = 2\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d74', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 4\\sin^2(x) dx$.', '$2\\pi$‎‏‎', '$2\\pi/2$', '$4\\pi$', '$\\pi$', 'option_a', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 4\\sin^2(x) dx = \\int_{0}^{\\pi} 2(1 - \\cos(2x)) dx = 2 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 2 \\left( (\\pi - 0) - (0 - 0) \\right) = 2\\pi$.', 1);
