INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d73', '6a422a4990ab47510c6f7d5f', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi} 10\\sin^2(x) dx$.', '$10\\pi$', '$5\\pi$‎‏‎', '$5\\pi/2$', '$\\pi$', 'option_b', NULL, 'Use the double-angle identity $\\sin^2(x) = \\frac{1 - \\cos(2x)}{2}$:\n$\\int_{0}^{\\pi} 10\\sin^2(x) dx = \\int_{0}^{\\pi} 5(1 - \\cos(2x)) dx = 5 \\left[ x - \\frac{\\sin(2x)}{2} \\right]_{0}^{\\pi}$\n$= 5 \\left( (\\pi - 0) - (0 - 0) \\right) = 5\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d83', '6a422a4a90ab47510c6f7d76', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi/2} 6\\sin^2(x)\\cos(x) dx$.', '$2$‎‏‎', '$6$', '$1$', '$0$', 'option_a', NULL, 'Let $u = \\sin(x) \\implies du = \\cos(x) dx$.\nWhen $x = 0, u = 0$. When $x = \\pi/2, u = 1$.\nRewrite the integral:\n$\\int_{0}^{1} 6u^2 du = \\left[ 2u^3 \\right]_{0}^{1} = 2(1)^3 - 0 = 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d85', '6a422a4a90ab47510c6f7d76', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi/2} 12\\sin^2(x)\\cos(x) dx$.', '$12$', '$4$‎‏‎', '$1$', '$0$', 'option_b', NULL, 'Let $u = \\sin(x) \\implies du = \\cos(x) dx$.\nWhen $x = 0, u = 0$. When $x = \\pi/2, u = 1$.\nRewrite the integral:\n$\\int_{0}^{1} 12u^2 du = \\left[ 4u^3 \\right]_{0}^{1} = 4(1)^3 - 0 = 4$.', 1);
