INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d84', '6a422a4a90ab47510c6f7d76', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi/2} 9\\sin^2(x)\\cos(x) dx$.', '$0$', '$1$', '$3$‎‏‎', '$9$', 'option_c', NULL, 'Let $u = \\sin(x) \\implies du = \\cos(x) dx$.\nWhen $x = 0, u = 0$. When $x = \\pi/2, u = 1$.\nRewrite the integral:\n$\\int_{0}^{1} 9u^2 du = \\left[ 3u^3 \\right]_{0}^{1} = 3(1)^3 - 0 = 3$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d87', '6a422a4a90ab47510c6f7d76', 'Evaluate the trigonometric definite integral: $\\int_{0}^{\\pi/2} 6\\sin^2(x)\\cos(x) dx$.', '$0$', '$2$‎‏‎', '$6$', '$1$', 'option_b', NULL, 'Let $u = \\sin(x) \\implies du = \\cos(x) dx$.\nWhen $x = 0, u = 0$. When $x = \\pi/2, u = 1$.\nRewrite the integral:\n$\\int_{0}^{1} 6u^2 du = \\left[ 2u^3 \\right]_{0}^{1} = 2(1)^3 - 0 = 2$.', 1);
