INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7d90', '6a422a4a90ab47510c6f7d8d', 'Evaluate the inverse trigonometric integral: $\\int_{0}^{4} \\frac{1}{16 + x^2} dx$.', '$\\pi/16$', '$\\pi/(16)$‎‏‎', '$\\pi$', '$\\pi/8$', 'option_b', NULL, 'Recall that $\\int \\frac{1}{a^2 + x^2} dx = \\frac{1}{a} \\arctan\\left(\\frac{x}{a}\\right)$.\nEvaluate from $0$ to $4$:\n$\\left[ \\frac{1}{4} \\arctan\\left(\\frac{x}{4}\\right) \\right]_{0}^{4} = \\frac{1}{4} \\arctan(1) - 0 = \\frac{1}{4} \\left(\\frac{\\pi}{4}\\right) = \\frac{\\pi}{16}$.', 1);
