INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7da0', '6a422a4a90ab47510c6f7d8d', 'Evaluate the inverse trigonometric integral: $\\int_{0}^{4} \\frac{1}{16 + x^2} dx$.', '$\\pi/16$', '$\\pi$', '$\\pi/(16)$‎‏‎', '$\\pi/8$', 'option_c', NULL, 'Recall that $\\int \\frac{1}{a^2 + x^2} dx = \\frac{1}{a} \\arctan\\left(\\frac{x}{a}\\right)$.\nEvaluate from $0$ to $4$:\n$\\left[ \\frac{1}{4} \\arctan\\left(\\frac{x}{4}\\right) \\right]_{0}^{4} = \\frac{1}{4} \\arctan(1) - 0 = \\frac{1}{4} \\left(\\frac{\\pi}{4}\\right) = \\frac{\\pi}{16}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7da8', '6a422a4a90ab47510c6f7da4', 'Using integration by parts, evaluate the definite integral: $\\int_{1}^{e} 20x\\ln(x) dx$.', '$10e²$', '$5e²$', '$5e² + 5$‎‏‎', '$5e² - 5$', 'option_c', NULL, 'Let $u = \\ln(x) \\implies du = \\frac{1}{x} dx$, and $dv = 20x \\, dx \\implies v = 10x^2$.\nUsing the integration by parts formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int 20x\\ln(x) dx = \\left[ 10x^2\\ln(x) \\right]_{1}^{e} - \\int_{1}^{e} 10x^2 \\left(\\frac{1}{x}\\right) dx$\n$= 10e^2 - \\left[ 5x^2 \\right]_{1}^{e} = 10e^2 - (5e^2 - 5) = 5e^2 + 5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7da9', '6a422a4a90ab47510c6f7da4', 'Using integration by parts, evaluate the definite integral: $\\int_{1}^{e} 8x\\ln(x) dx$.', '$2e² - 2$', '$2e² + 2$‎‏‎', '$2e²$', '$4e²$', 'option_b', NULL, 'Let $u = \\ln(x) \\implies du = \\frac{1}{x} dx$, and $dv = 8x \\, dx \\implies v = 4x^2$.\nUsing the integration by parts formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int 8x\\ln(x) dx = \\left[ 4x^2\\ln(x) \\right]_{1}^{e} - \\int_{1}^{e} 4x^2 \\left(\\frac{1}{x}\\right) dx$\n$= 4e^2 - \\left[ 2x^2 \\right]_{1}^{e} = 4e^2 - (2e^2 - 2) = 2e^2 + 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dab', '6a422a4a90ab47510c6f7da4', 'Using integration by parts, evaluate the definite integral: $\\int_{1}^{e} 16x\\ln(x) dx$.', '$4e² - 4$', '$4e² + 4$‎‏‎', '$8e²$', '$4e²$', 'option_b', NULL, 'Let $u = \\ln(x) \\implies du = \\frac{1}{x} dx$, and $dv = 16x \\, dx \\implies v = 8x^2$.\nUsing the integration by parts formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int 16x\\ln(x) dx = \\left[ 8x^2\\ln(x) \\right]_{1}^{e} - \\int_{1}^{e} 8x^2 \\left(\\frac{1}{x}\\right) dx$\n$= 8e^2 - \\left[ 4x^2 \\right]_{1}^{e} = 8e^2 - (4e^2 - 4) = 4e^2 + 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dae', '6a422a4a90ab47510c6f7da4', 'Using integration by parts, evaluate the definite integral: $\\int_{1}^{e} 12x\\ln(x) dx$.', '$3e² + 3$‎‏‎', '$3e²$', '$6e²$', '$3e² - 3$', 'option_a', NULL, 'Let $u = \\ln(x) \\implies du = \\frac{1}{x} dx$, and $dv = 12x \\, dx \\implies v = 6x^2$.\nUsing the integration by parts formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int 12x\\ln(x) dx = \\left[ 6x^2\\ln(x) \\right]_{1}^{e} - \\int_{1}^{e} 6x^2 \\left(\\frac{1}{x}\\right) dx$\n$= 6e^2 - \\left[ 3x^2 \\right]_{1}^{e} = 6e^2 - (3e^2 - 3) = 3e^2 + 3$.', 1);
