INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7db9', '6a422a4a90ab47510c6f7da4', 'Using integration by parts, evaluate the definite integral: $\\int_{1}^{e} 8x\\ln(x) dx$.', '$2e²$', '$4e²$', '$2e² + 2$‎‏‎', '$2e² - 2$', 'option_c', NULL, 'Let $u = \\ln(x) \\implies du = \\frac{1}{x} dx$, and $dv = 8x \\, dx \\implies v = 4x^2$.\nUsing the integration by parts formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int 8x\\ln(x) dx = \\left[ 4x^2\\ln(x) \\right]_{1}^{e} - \\int_{1}^{e} 4x^2 \\left(\\frac{1}{x}\\right) dx$\n$= 4e^2 - \\left[ 2x^2 \\right]_{1}^{e} = 4e^2 - (2e^2 - 2) = 2e^2 + 2$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dc3', '6a422a4a90ab47510c6f7dbb', 'Using integration by parts, evaluate the definite integral: $\\int_{0}^{\\pi/2} 5x\\cos(x) dx$.', '$0$', '$5\\pi/2 - 5$‎‏‎', '$5\\pi - 5$', '$5\\pi/2$', 'option_b', NULL, 'Let $u = x \\implies du = dx$, and $dv = 5\\cos(x) dx \\implies v = 5\\sin(x)$.\nUsing the formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int_{0}^{\\pi/2} 5x\\cos(x) dx = \\left[ 5x\\sin(x) \\right]_{0}^{\\pi/2} - \\int_{0}^{\\pi/2} 5\\sin(x) dx$\n$= 5\\left(\\frac{\\pi}{2}\\right)(1) - \\left[ -5\\cos(x) \\right]_{0}^{\\pi/2} = \\frac{5\\pi}{2} - 5$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dc5', '6a422a4a90ab47510c6f7dbb', 'Using integration by parts, evaluate the definite integral: $\\int_{0}^{\\pi/2} 3x\\cos(x) dx$.', '$3\\pi - 3$', '$3\\pi/2$', '$0$', '$3\\pi/2 - 3$‎‏‎', 'option_d', NULL, 'Let $u = x \\implies du = dx$, and $dv = 3\\cos(x) dx \\implies v = 3\\sin(x)$.\nUsing the formula $\\int u \\, dv = uv - \\int v \\, du$:\n$\\int_{0}^{\\pi/2} 3x\\cos(x) dx = \\left[ 3x\\sin(x) \\right]_{0}^{\\pi/2} - \\int_{0}^{\\pi/2} 3\\sin(x) dx$\n$= 3\\left(\\frac{\\pi}{2}\\right)(1) - \\left[ -3\\cos(x) \\right]_{0}^{\\pi/2} = \\frac{3\\pi}{2} - 3$.', 1);
