INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dd5', '6a422a4a90ab47510c6f7dd2', 'Evaluate the definite integral with exponential limits: $\\int_{0}^{1} 8xe^{x^2} dx$.', '$4e + 4$', '$4e$', '$4e - 4$‎‏‎', '$8e$', 'option_c', NULL, 'Let $u = x^2 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} 4 e^{x^2} (2x\\,dx) = \\int_{0}^{1} 4 e^u du = \\left[ 4e^u \\right]_{0}^{1} = 4e^1 - 4e^0 = 4e - 4$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7dd6', '6a422a4a90ab47510c6f7dd2', 'Evaluate the definite integral with exponential limits: $\\int_{0}^{1} 10xe^{x^2} dx$.', '$10e$', '$5e$', '$5e + 5$', '$5e - 5$‎‏‎', 'option_d', NULL, 'Let $u = x^2 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} 5 e^{x^2} (2x\\,dx) = \\int_{0}^{1} 5 e^u du = \\left[ 5e^u \\right]_{0}^{1} = 5e^1 - 5e^0 = 5e - 5$.', 1);
