INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7ddb', '6a422a4a90ab47510c6f7dd2', 'Evaluate the definite integral with exponential limits: $\\int_{0}^{1} 4xe^{x^2} dx$.', '$2e + 2$', '$2e$', '$2e - 2$‎‏‎', '$4e$', 'option_c', NULL, 'Let $u = x^2 \\implies du = 2x\\,dx$.\nRewrite the integral:\n$\\int_{0}^{1} 2 e^{x^2} (2x\\,dx) = \\int_{0}^{1} 2 e^u du = \\left[ 2e^u \\right]_{0}^{1} = 2e^1 - 2e^0 = 2e - 2$.', 1);
