INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7df6', '6a422a4a90ab47510c6f7de9', 'Using Wallis\' formula, evaluate: $\\int_{0}^{\\pi/2} \\sin^2(x) dx$.', '$\\pi/4$‎‏‎', '$\\pi/8$', '$1/2$', '$\\pi/2$', 'option_a', NULL, 'Wallis\' Formula for an even power $n=2$ states:\n$\\int_{0}^{\\pi/2} \\sin^2(x) dx = \\frac{2-1}{2} \\times \\frac{\\pi}{2} = \\frac{1}{2} \\times \\frac{\\pi}{2} = \\frac{\\pi}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7df7', '6a422a4a90ab47510c6f7de9', 'Using Wallis\' formula, evaluate: $\\int_{0}^{\\pi/2} \\sin^3(x) dx$.', '$\\pi/4$', '$3/4$', '$2/3$‎‏‎', '$1/3$', 'option_c', NULL, 'Wallis\' Formula for an odd power $n=3$ states:\n$\\int_{0}^{\\pi/2} \\sin^3(x) dx = \\frac{3-1}{3} \\times 1 = \\frac{2}{3}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7df8', '6a422a4a90ab47510c6f7de9', 'Using Wallis\' formula, evaluate: $\\int_{0}^{\\pi/2} \\sin^2(x) dx$.', '$\\pi/4$‎‏‎', '$1/2$', '$\\pi/2$', '$\\pi/8$', 'option_a', NULL, 'Wallis\' Formula for an even power $n=2$ states:\n$\\int_{0}^{\\pi/2} \\sin^2(x) dx = \\frac{2-1}{2} \\times \\frac{\\pi}{2} = \\frac{1}{2} \\times \\frac{\\pi}{2} = \\frac{\\pi}{4}$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e0a', '6a422a4a90ab47510c6f7e00', 'Find the area of the region bounded by the curve $y = 3x^2$, the $x$-axis, and the vertical lines $x = 0$ and $x = 3$.', '$18$', '$54$', '$27$‎‏‎', '$33$', 'option_c', NULL, 'The area $A$ is given by the definite integral:\n$A = \\int_{0}^{3} 3x^2 dx = \\left[ \\frac{3}{3}x^3 \\right]_{0}^{3} = \\frac{3}{3}(27) - 0 = 27 = 27$.', 1);
