INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e1c', '6a422a4a90ab47510c6f7e17', 'Find the volume of the solid generated when the region bounded by $y = 2\\sqrt{x}$, the $x$-axis, from $x=0$ to $x=2$ is rotated $360^\\circ$ about the $x$-axis.', '$4\\pi$', '$16\\pi$', '$16\\pi$', '$8\\pi$‎‏‎', 'option_d', NULL, 'The volume $V$ of revolution about the $x$-axis is:\n$V = \\pi \\int_{a}^{b} [f(x)]^2 dx = \\pi \\int_{0}^{2} (2\\sqrt{x})^2 dx = \\pi \\int_{0}^{2} 4x \\, dx$\n$= \\pi \\left[ \\frac{4}{2}x^2 \\right]_{0}^{2} = \\pi \\left( \\frac{4}{2}(4) - 0 \\right) = 8\\pi = 8\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e20', '6a422a4a90ab47510c6f7e17', 'Find the volume of the solid generated when the region bounded by $y = 2\\sqrt{x}$, the $x$-axis, from $x=0$ to $x=2$ is rotated $360^\\circ$ about the $x$-axis.', '$8\\pi$‎‏‎', '$16\\pi$', '$16\\pi$', '$4\\pi$', 'option_a', NULL, 'The volume $V$ of revolution about the $x$-axis is:\n$V = \\pi \\int_{a}^{b} [f(x)]^2 dx = \\pi \\int_{0}^{2} (2\\sqrt{x})^2 dx = \\pi \\int_{0}^{2} 4x \\, dx$\n$= \\pi \\left[ \\frac{4}{2}x^2 \\right]_{0}^{2} = \\pi \\left( \\frac{4}{2}(4) - 0 \\right) = 8\\pi = 8\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e27', '6a422a4a90ab47510c6f7e17', 'Find the volume of the solid generated when the region bounded by $y = 5\\sqrt{x}$, the $x$-axis, from $x=0$ to $x=2$ is rotated $360^\\circ$ about the $x$-axis.', '$25\\pi$', '$100\\pi$', '$100\\pi$', '$50\\pi$‎‏‎', 'option_d', NULL, 'The volume $V$ of revolution about the $x$-axis is:\n$V = \\pi \\int_{a}^{b} [f(x)]^2 dx = \\pi \\int_{0}^{2} (5\\sqrt{x})^2 dx = \\pi \\int_{0}^{2} 25x \\, dx$\n$= \\pi \\left[ \\frac{25}{2}x^2 \\right]_{0}^{2} = \\pi \\left( \\frac{25}{2}(4) - 0 \\right) = 50\\pi = 50\\pi$.', 1);
