INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e1d', '6a422a4a90ab47510c6f7e17', 'Find the volume of the solid generated when the region bounded by $y = 3\\sqrt{x}$, the $x$-axis, from $x=0$ to $x=2$ is rotated $360^\\circ$ about the $x$-axis.', '$18\\pi$‎‏‎', '$9\\pi$', '$36\\pi$', '$36\\pi$', 'option_a', NULL, 'The volume $V$ of revolution about the $x$-axis is:\n$V = \\pi \\int_{a}^{b} [f(x)]^2 dx = \\pi \\int_{0}^{2} (3\\sqrt{x})^2 dx = \\pi \\int_{0}^{2} 9x \\, dx$\n$= \\pi \\left[ \\frac{9}{2}x^2 \\right]_{0}^{2} = \\pi \\left( \\frac{9}{2}(4) - 0 \\right) = 18\\pi = 18\\pi$.', 1);
