INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e2b', '6a422a4a90ab47510c6f7e17', 'Find the volume of the solid generated when the region bounded by $y = 5\\sqrt{x}$, the $x$-axis, from $x=0$ to $x=2$ is rotated $360^\\circ$ about the $x$-axis.', '$100\\pi$', '$100\\pi$', '$50\\pi$‎‏‎', '$25\\pi$', 'option_c', NULL, 'The volume $V$ of revolution about the $x$-axis is:\n$V = \\pi \\int_{a}^{b} [f(x)]^2 dx = \\pi \\int_{0}^{2} (5\\sqrt{x})^2 dx = \\pi \\int_{0}^{2} 25x \\, dx$\n$= \\pi \\left[ \\frac{25}{2}x^2 \\right]_{0}^{2} = \\pi \\left( \\frac{25}{2}(4) - 0 \\right) = 50\\pi = 50\\pi$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e33', '6a422a4a90ab47510c6f7e2e', 'Use the Trapezium Rule with $2$ equal intervals ($h = 1$) to approximate the definite integral $\\int_{0}^{2} 2x^2 dx$.', '$5$', '$6$‎‏‎', '$12$', '$7$', 'option_b', NULL, 'With $h = 1$, the ordinates are at $x_0 = 0$, $x_1 = 1$, $x_2 = 2$.\nEvaluate the function $f(x) = 2x^2$ at these points:\n$y_0 = f(0) = 0$, $y_1 = f(1) = 2$, $y_2 = f(2) = 8$.\nBy Trapezium Rule:\n$Area \\approx \\frac{h}{2} [ y_0 + 2y_1 + y_2 ] = \\frac{1}{2} [ 0 + 2(2) + 8 ] = \\frac{1}{2} [ 12 ] = 6 = 6$.', 1);
INSERT INTO `questions` (`id`, `topic_id`, `text`, `a`, `b`, `c`, `d`, `correct_option`, `diagram_url`, `explanation`, `is_refined`) VALUES ('6a422a4a90ab47510c6f7e37', '6a422a4a90ab47510c6f7e2e', 'Use the Trapezium Rule with $2$ equal intervals ($h = 1$) to approximate the definite integral $\\int_{0}^{2} 2x^2 dx$.', '$7$', '$6$‎‏‎', '$12$', '$5$', 'option_b', NULL, 'With $h = 1$, the ordinates are at $x_0 = 0$, $x_1 = 1$, $x_2 = 2$.\nEvaluate the function $f(x) = 2x^2$ at these points:\n$y_0 = f(0) = 0$, $y_1 = f(1) = 2$, $y_2 = f(2) = 8$.\nBy Trapezium Rule:\n$Area \\approx \\frac{h}{2} [ y_0 + 2y_1 + y_2 ] = \\frac{1}{2} [ 0 + 2(2) + 8 ] = \\frac{1}{2} [ 12 ] = 6 = 6$.', 1);
