CREATE DATABASE IF NOT EXISTS `premed_portal` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `premed_portal`;

SET FOREIGN_KEY_CHECKS = 0;

-- Table `students`
CREATE TABLE IF NOT EXISTS `students` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) NULL,
  `matric_no` VARCHAR(100) NOT NULL UNIQUE,
  `phone` VARCHAR(50) NULL,
  `password` VARCHAR(255) NOT NULL,
  `department` VARCHAR(150) NOT NULL,
  `strength` VARCHAR(255) NOT NULL,
  `session_token_id` VARCHAR(255) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_student_matric` (`matric_no`),
  INDEX `idx_student_dept` (`department`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `courses`
CREATE TABLE IF NOT EXISTS `courses` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `code` VARCHAR(50) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `icon` VARCHAR(50) DEFAULT 'Book',
  `scheduled_date` VARCHAR(100) NULL,
  `end_date` VARCHAR(100) NULL,
  `is_mock` TINYINT(1) DEFAULT 1,
  `is_master` TINYINT(1) DEFAULT 0,
  `is_locked` TINYINT(1) DEFAULT 1,
  `results_hidden` TINYINT(1) DEFAULT 0,
  `results_locked` TINYINT(1) DEFAULT 1,
  `force_start` TINYINT(1) DEFAULT 0,
  `duration` INT DEFAULT 30,
  `question_limit` INT DEFAULT 20,
  `attempts_allowed` INT DEFAULT 1,
  `question_timer_limit` INT DEFAULT 0,
  `multicourse_config` TEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `topics`
CREATE TABLE IF NOT EXISTS `topics` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `course_id` VARCHAR(50) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `question_count` INT DEFAULT 0,
  `notes` LONGTEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_topic_course` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `questions`
CREATE TABLE IF NOT EXISTS `questions` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `topic_id` VARCHAR(50) NOT NULL,
  `text` LONGTEXT NOT NULL,
  `a` TEXT NOT NULL,
  `b` TEXT NOT NULL,
  `c` TEXT NULL,
  `d` TEXT NULL,
  `correct_option` VARCHAR(10) NOT NULL,
  `diagram_url` TEXT NULL,
  `explanation` LONGTEXT NULL,
  `is_refined` TINYINT(1) DEFAULT 0,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_question_topic` (`topic_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `results`
CREATE TABLE IF NOT EXISTS `results` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `student_id` VARCHAR(50) NOT NULL,
  `course_id` VARCHAR(50) NOT NULL,
  `parent_course_id` VARCHAR(50) NULL,
  `attempt_id` VARCHAR(100) NULL,
  `device_id` VARCHAR(100) NULL,
  `total_score` INT NOT NULL,
  `total_questions` INT NOT NULL,
  `percentage` DECIMAL(5,2) NOT NULL,
  `grade` VARCHAR(10) NOT NULL,
  `question_ids` LONGTEXT NULL,
  `topic_breakdown` LONGTEXT NULL,
  `student_answers` LONGTEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_result_student` (`student_id`),
  INDEX `idx_result_course` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `announcements`
CREATE TABLE IF NOT EXISTS `announcements` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `content` TEXT NOT NULL,
  `type` VARCHAR(50) DEFAULT 'info',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `settings`
CREATE TABLE IF NOT EXISTS `settings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `key_name` VARCHAR(100) NOT NULL UNIQUE,
  `value` LONGTEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;








SET FOREIGN_KEY_CHECKS = 1;
